(window.GIM_TS=window.GIM_TS||{})["Shevuot.0"]={"from":0,"a":[["\u0003שבועות\u0004 (ביטוי \"כי תשבע לבטא בשפתים\", ויקרא ה, ד) שחייבים עליהן קרבן עולה ויורד (לפי מצבו הכלכלי של הנשבע) אם נעשו בשוגג — הריהן \u0003שתים\u0004 המוזכרות בכתוב (\"להרע או להיטיב\". ויקרא ה, ד), כשנשבע לעשות דבר־מה או להימנע מלעשותו ועבר על שבועתו, \u0003שהן ארבע\u0004 שיש עוד שתים שאינן כתובות, כשנשבע שבועת שקר על העבר, שעשה דבר־מה והוא לא עשאו, או שנשבע שלא עשה והוא עשאו. מתוך שהוזכרה הלכה שהיא \"שתים שהן ארבע\", מובאות עוד הלכות שונות שיש בהן מבנה דומה.","\u0003ידיעות הטומאה\u0004 אופנים שנעלם מידיעת אדם שהוא נכנס למקדש או אכל קדשים כשהוא טמא, ואז כאשר נודע לו הוא מתחייב בקרבן עולה ויורד על שגגתו (ויקרא ה ג), \u0003שתים שהן ארבע,\u0004 שתים כתובות — כשלא ידע שהוא טמא, ושתים שאינן כתובות — כשלא ידע שנכנס למקדש או שאכל בשר קדשים.","\u0003יציאות\u0004 (הוצאות) \u0003השבת\u0004 אופנים של הוצאה מרשות לרשות בשבת, שחייב עליהם, \u0003שתים שהן ארבע,\u0004 שתים כתובות — שהוציא מרשות היחיד לרשות הרבים, בין כשהוא עומד ברשות היחיד ומוציא, ובין שעומד ברשות הרבים ולוקח חפץ מרשות היחיד ומוציאו אליו לרשות הרבים. ושתים שאינן כתובות — כשהכניס מרשות הרבים לרשות היחיד.","\u0003מראות נגעים\u0004 סוג כתמים לבנים המהווים סימני הצרעת, \u0003שנים שהן ארבעה,\u0004 שנים כתובים — השאת והבהרת, ושנים שאינם כתובים — הדומים להם, אבל אינם בהירים כמותם. מכאן באה המשנה לדון בהרחבה בידיעות הטומאה, כיצד מתכפר עוון זה.","\u0003את שיש בה\u0004 בעבירה זו \u0003ידיעה בתחלה\u0004 שידע שהוא טמא קודם שנכנס למקדש או שאכל את הקודש, \u0003וידיעה בסוף\u0004 לאחר מעשה, שנודע לו שעבר עבירה זו, \u0003ו\u0004היה \u0003העלם\u0004 ידיעה \u0003בינתים\u0004 ששכח שהוא טמא, או שלא שם לב שהוא נכנס למקדש או אוכל קודש — \u0003הרי זה\u0004 מתכפר \u0003ב\u0004קרבן \u0003עולה ויורד\u0004 לפי מצבו הכלכלי, כמבואר בתורה (ויקרא ה, ו—יג) שאם הוא עשיר מביא חטאת בהמה (כשבה או שעירה), ואם הוא עני מביא חטאת העוף ועולת העוף, ואם אין ידו משגת אף לזה — מביא מנחה לחטאת עשירית האיפה סולת.","אם \u0003יש בה\u0004 בעבירה זו \u0003ידיעה בתחלה\u0004 שידע מתחילה שהוא טמא, \u0003ואין בה ידיעה בסוף\u0004 ששכח ולא נודע לו לאחר מכן שנכנס למקדש או שאכל את הקודש בטומאה — \u0003שעיר הנעשה בפנים\u0004 שהכהן הגדול מזה מדמו בקדש הקדשים ביום הכיפורים, \u0003ויום הכפורים\u0004 עצמו, \u0003תולה\u0004 את כפרתו, להגן עליו לפי שעה מן העונש, \u0003עד שיודע לו\u0004 חטאו, \u0003ו\u0004אז \u0003יביא\u0004 חטאתו, ויתכפר לו \u0003ב\u0004קרבן \u0003עולה ויורד.\u0004","אם \u0003אין בה ידיעה בתחלה\u0004 שלא ידע מתחילה שהוא טמא או שהוא נכנס למקדש או אוכל קודש, \u0003אבל יש בה ידיעה בסוף\u0004 שלאחר מעשה נודע לו הדבר — \u0003שעיר הנעשה\u0004 ביום הכיפורים \u0003בחוץ\u0004 שדמו נזרק על מזבח העולה (מזבח החיצון), כחלק ממוספי היום, \u0003ויום הכפורים\u0004 עצמו \u0003מכפר.\u0004 ומנין שעל כך מכפר השעיר הנעשה בחוץ? \u0003שנאמר\u0004 במוספי יום הכיפורים: \"שעיר עזים אחד חטאת \u0003מלבד חטאת הכפורים\"\u0004 (במדבר כט, יא), ומהשוואה זו יש ללמוד: \u0003על מה שזה\u0004 (חטאת הכיפורים, השעיר הנעשה בפנים) \u0003מכפר\u0004 — \u0003זה\u0004 (השעיר הנעשה בחוץ) \u0003מכפר, מה הפנימי אין מכפר אלא על דבר שיש בה ידיעה\u0004 (בתחילה) — \u0003אף החיצון אין מכפר אלא על דבר שיש בה ידיעה\u0004 (בסוף).","\u0003ועל\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף\u0004 שכלל אינו יודע שעבר עבירה — \u0003שעירי\u0004 חטאת הבאים כחלק ממוספי \u0003הרגלים\u0004 \u0003ו\u0004כן \u0003שעירי\u0004 חטאת של מוספי \u0003ראשי חדשים מכפרין, דברי ר' יהודה.\u0004 \u0003ר' שמעון אומר: שעירי הרגלים מכפרין\u0004 על הטמא שנכנס למקדש או אכל בשר קודש, ולא היתה לו ידיעה כלל, \u0003אבל לא שעירי ראשי\u0004 \u0003חדשים. ועל מה שעירי ראשי חדשים מכפרין —\u0004"],["\u0003על\u0004 האיש \u0003הטהור שאכל את\u0004 בשר הקודש \u0003הטמא.\u0004","\u0003ר' מאיר אומר:\u0004 אין להבחין ביניהם, אלא \u0003כל השעירין\u0004 הבאים במוספים (בראש חודש, בחגים וביום הכיפורים) \u0003כפרתן שוה\u0004 — \u0003על טומאת מקדש וקדשיו.\u0004","ובענין זה נמסר, \u0003היה ר' שמעון אומר\u0004 כפי שהובא קודם בשמו: \u0003שעירי ראשי חדשים מכפרים על הטהור שאכל את הטמא, ו\u0004שעירים \u0003של רגלים מכפרין על\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף, ו\u0004שעיר החיצון \u0003של יום הכפורים מכפר על שאין בה ידיעה בתחלה אבל יש בה ידיעה בסוף.\u0004","\u0003אמרו לו\u0004 חכמים: \u0003מהו שיקרבו זה בזה\u0004, האם אפשר, למשל, להקריב שעיר שהופרש מתחילה למוספי רגלים, כמוסף יום הכיפורים? שהרי כפרתם אינה שווה. \u0003אמר להן\u0004 ר' שמעון: \u0003יקרבו. אמרו לו: הואיל ואין כפרתן שוה, היאך קרבין זה בזה? אמר להם:\u0004 אף שיש הבדל ביניהם בפרטי הכפרה, מכל מקום \u0003כולן\u0004 דומים זה לזה בעיקרם, שהרי הם \u0003באין לכפר על טומאת מקדש וקדשיו.\u0004","\u0003ר' שמעון בן יהודה אומר משמו\u0004 של ר' שמעון (בר יוחאי) בנוסח שונה קצת: \u0003שעירי ראשי חדשים מכפרין על הטהור שאכל את הטמא. מוסיף\u0004 (יתר) \u0003עליהן\u0004 שעירי מוספים \u0003של רגלים, שמכפרין\u0004 גם \u0003על טהור שאכל את הטמא, ו\u0004גם \u0003על\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף.\u0004","\u0003מוסיף עליהן\u0004 שעיר הנעשה בחוץ \u0003של יום הכפורים, שהן מכפרין\u0004 גם \u0003על הטהור שאכל את הטמא, ו\u0004גם \u0003על\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף,\u0004 כמו שעירי הרגלים, \u0003ו\u0004בנוסף לכך גם \u0003על\u0004 טומאה \u0003שאין בה ידיעה בתחלה אבל יש בה ידיעה בסוף.\u0004","\u0003אמרו לו\u0004 לר' שמעון: \u0003מהו שיקרבו זה בזה? אמר להם: הן. אמרו לו: אם כן יהיו של יום הכפורים קרבין בראשי חדשים,\u0004 שהרי בכלל כפרתם גם הטהור שאכל את הטמא\u0003,\u0004 שמכפרים עליו שעירי ראשי חדשים, \u0003אבל היאך של ראשי חדשים קרבין ביום הכפורים לכפר כפרה שאינה שלה? אמר להם: כולן,\u0004 כל שעירי המוספים, \u0003באין\u0004 בעיקר \u0003לכפר על טומאת מקדש וקדשיו,\u0004 ולכן אין זו כפרה שאינה שלהם.","עד כאן עסקנו בכפרה של טומאת מקדש וקדשיו שנעשתה בשגגה. וממשיכים: \u0003ועל זדון טומאת מקדש וקדשיו\u0004 — \u0003שעיר הנעשה בפנים\u0004 (שמזים מדמו בקודש הקדשים ביום הכיפורים) \u0003ויום הכפורים\u0004 עצמו \u0003מכפרין.\u0004","\u0003על שאר עבירות שבתורה: הקלות והחמורות, הזדונות והשגגות,\u0004 \u0003הודע ולא הודע\u0004 (שיש בהן ידיעה של האיסור, ושאין בהן ידיעה), מצוות \u0003עשה ו\u0004מצוות \u0003לא תעשה,\u0004 ואף עבירות שחייבים עליהן \u0003כריתות ומיתות בית דין\u0004 — \u0003שעיר המשתלח מכפר.\u0004","\u0003אחד ישראלים ואחד כהנים ואחד כהן משוח\u0004 (כהן גדול, שנמשח בשמן המשחה), כולם שווים בכפרה זו של שעיר המשתלח. אם כן, \u0003מה בין ישראלים לכהנים ולכהן משוח? אלא שהפר\u0004 שמקריב הכהן הגדול ביום הכיפורים \u0003מכפר על הכהנים על טומאת מקדש וקדשיו,\u0004 מה שמכפרים השעירים הפנימי והחיצון על הישראלים.","\u0003ר' שמעון אומר:\u0004 אין השעיר המשתלח מכפר כלל על הכהנים, אלא \u0003כשם שדם השעיר הנעשה בפנים מכפר על ישראל\u0004 בטומאת מקדש וקדשיו — \u0003כך דם הפר,\u0004 שגם הוא נעשה בפנים, \u0003מכפר על הכהנים. כשם שוידויו של שעיר המשתלח מכפר על ישראל\u0004 בשאר עבירות — \u0003כך וידויו של פר מכפר על הכהנים\u0004 בשאר עבירות.","ותחילה שואלים לעצם מיקומה של מסכת זו: \u0003מכדי\u0004 \u0005[הואיל]\u0006 וה\u0003תנא מ\u0004מסכת \u0003מכות סליק\u0004 \u0005[עולה,\u0006 מסיים ובא], \u0003מאי שנא דתני\u0004 \u0005[מה שונה,\u0006 מהו הטעם \u0005ש\u0006הוא \u0005שונה]\u0006 אחריה מסכת \u0003שבועות?\u0004 מה הקשר ביניהן? ומשיבים: \u0003משום דתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 בסוף מסכת מכות: \u0003חייב על\u0004 הקפת (גילוח) פאת \u0003הראש,\u0004 בצדעיים, \u0003שתים, אחת מיכן\u0004 (מכאן) בצד זה של ראשו, \u0003ואחת מיכן\u0004 מן הצד השני של הראש,"],["\u0003ועל\u0004 השחתת \u0003הזקן\u0004 חייב \u0003שתים\u0004 על שתי פאות שיש \u0003מיכן\u0004 (מכאן) מצד זה של הפנים, \u0003ושתים מיכן\u0004 מצד זה של הפנים, \u0003ואחת מלמטה\u0004 (בסנטר), שהוא","\u0003חדא דמיחייב עלה תרתי\u0004 \u0005[\u0006עבירה \u0005אחת שמתחייב עליה שתים]\u0006 — \u0003תנא\u0004 \u0005[שנה]\u0006 גם את ההלכה הדומה: \u0003שבועות שתים שהן ארבע.\u0004","ושואלים לפרטי הדברים השנויים במשנה: \u0003מאי שנא הכא דתני להו לכולהו\u0004 \u0005[מה שונה כאן,\u0006 במשנה במסכת שבועות, \u0005ששנה את כולם]\u0006 את כל סוגי ההלכות שהן \"שתים שהן ארבע\", \u0003ומאי שנא גבי\u0004 \u0005[ומה שונה\u0006 במשנה \u0005אצל]\u0006 \u0003יציאות שבת\u0004 (במסכת שבת) \u0003ומראות נגעים\u0004 (במסכת נגעים) \u0003דלא קתני להו לכולהו\u0004 \u0005[שלא שנה את כולם]?\u0006","\u0003אמרי\u0004 \u0005[אומרים,\u0006 בתשובה\u0005]:\u0006 \u0003שבועות וידיעות הטומאה דגבי הדדי כתיבין\u0004 \u0005[שזה אצל זה\u0006 הן \u0005כתובות\u0006 בתורה\u0005]\u0006 (ויקרא ה, ג— ד), \u0003ודמיין אהדדי\u0004 \u0005[ו\u0006הן גם \u0005דומות\u0006 בדינן \u0005אלו לאלו]\u0006 \u0003בקרבן עולה ויורד\u0004 שחייב להביא עליהם, כמבואר באותה פרשה — \u0003תני להו גבי הדדי\u0004 \u0005[שנה אותן אלו אצל אלו],\u0006 משום הדמיון והקירבה, \u0003ואיידי דתנא תרתי תנא כולהו\u0004 \u0005[ומתוך ששנה שתים,\u0006 שתי הלכות שיש בהן \"שתים שהם ארבע\", \u0005שנה\u0006 את \u0005כולם],\u0006 גם שבת ומראות נגעים.","ועוד תמהים: \u0003פתח\u0004 את המשנה \u0003בשבועות, ומפרש\u0004 תחילה \u0003ידיעות הטומאה!\u0004 ומשיבים: \u0003איידי דזוטרין מילייהו, פסיק שרי להו\u0004 \u0005[מתוך שמועטים\u0006 יחסית \u0005ענייניהם\u0006 של ידיעות הטומאה, \u0005פסק,\u0006 חתך \u0005והתיר אותם,\u0006 נפטר מהם תחילה\u0005]\u0006 בשני הפרקים הראשונים של המסכת, \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 ענייני \u0003שבועות דנפישן מילייהו\u0004 \u0005[שמרובים ענייניהם].\u0006","ומפרשים את פרטי המשנה: \u0003שבועות\u0004 שחייב עליהן קרבן הריהן \u0003שתים שהן ארבע: שתים\u0004 לעתיד — \"שבועה \u0003שאוכל\"\u0004 ולא אכל, \u0003ו\u0004\"שבועה \u0003שלא אוכל\"\u0004 ואכל, \u0003שהן ארבע\u0004 — שנשבע לשקר על העבר: \"שבועה ש\u0003אכלתי\"\u0004 ולא אכל, \u0003ו\u0004\"שבועה \u0003שלא אכלתי\"\u0004 ואכל.","\u0003ידיעות הטומאה\u0004 שנעלמו ממנו, \u0003שתים שהן ארבע: שתים\u0004 — \u0003ידיעת טומאת קדש\u0004 שנעלם ממנו שהוא טמא כשאכל קודש, \u0003וידיעת טומאת מקדש\u0004 שנעלם ממנו שנכנס למקדש כשהוא טמא, \u0003שהן ארבע\u0004 — שלא ידע שזהו \u0003קדש, ו\u0004שלא ידע שנכנס ל\u0003מקדש.\u0004","\u0003יציאות שבת שתים שהן ארבע: שתים\u0004 — \u0003הוצאה\u0004 של ה\u0003עני,\u0004 שעומד ברשות הרבים ומוציא לשם חפץ מן הבית, שהוא רשות היחיד, \u0003והוצאה\u0004 של \u0003בעל הבית,\u0004 שעומד ברשות היחיד ומוציא משם חפץ לרשות הרבים. \u0003שהן ארבע\u0004 — \u0003הכנסה\u0004 של ה\u0003עני,\u0004 העומד ברשות הרבים, ומכניס מרשות הרבים לרשות היחיד, \u0003והכנסה\u0004 של \u0003בעל הבית,\u0004 העומד ברשות היחיד, ומכניס מרשות הרבים אליו לרשות היחיד.","\u0003מראות נגעים שנים שהן ארבעה: שנים\u0004 — \u0003שאת ובהרת\u0004 הכתובים בתורה (ראה ויקרא יג, ב), \u0003שהן ארבעה\u0004 — \u0003שאת ותולדתה, בהרת ותולדתה.\u0004","לאחר שפירשנו מה הם כל אותם \"שתים שהן ארבע\", מתקשים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 שלכאורה היא \u0003לא\u0004 כשיטת \u0003ר' ישמעאל ולא\u0004 כשיטת \u0003ר' עקיבא,\u0004 שכן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ר' ישמעאל\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 בענין שבועות: \u0003אינו חייב אלא\u0004 זה שנשבע \u0003על העתיד לבוא\u0004 ולא קיים את שבועתו, אבל אינו חייב על שבועה על העבר ואינן אלא שתים. \u0003אי\u0004 \u0005[אם]\u0006 \u0003ר' עקיבא\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 בענין ידיעות הטומאה: \u0003על העלם טומאה הוא חייב, ואינו חייב על העלם מקדש\u0004 או על העלם קודש, ואינן אלא שתים!","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 והסבר את משנתנו כשיטת \u0003ר' ישמעאל, איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כשיטת \u0003ר' עקיבא.\u0004 ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 לשיטת \u0003ר' ישמעאל,\u0004 כוונת המשנה היא: שבועות שתים שהן ארבע, \u0003מהן לחיוב\u0004 קרבן (בשבועה לעתיד), \u0003ומהן לפטור\u0004 (בשבועה לשעבר). \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לשיטת \u0003ר' עקיבא,\u0004 אף הוא מונה ארבע \u0003מהן לחיוב\u0004 קרבן \u0003ומהן לפטור.\u0004","ותוהים: וכי יכול אתה לפרש שמדובר במשנה על דברים שהם \u0003לפטור?\u0004"],["\u0003הא דומיא\u0004 \u0005[הרי בדומה]\u0006 ל\u0003מראות נגעים קתני\u0004 \u0005[הוא שונה]\u0006 את שאר הדינים במשנה, ויש להשוותם זה לזה ולומר: \u0003מה התם כולהו לחיובא\u0004 \u0005[מה שם,\u0006 בנגעים, \u0005כולם לחיוב],\u0006 שעל כל אחד מארבעת המראות מביא המצורע קרבן לטהרתו, \u0003אף הכא נמי כולהו לחיובא\u0004 \u0005[כאן,\u0006 לענין שבועות או ידיעות הטומאה, \u0005גם כן כולן,\u0006 כל הארבע הן \u0005לחיוב]!\u0006","ומסבירים באופן אחר: \u0003לעולם\u0004 משנתנו כשיטת \u0003ר' ישמעאל\u0004 היא, \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא מחייב ר' ישמעאל\u0004 על שבועה \u0003לשעבר\u0004 הרי זה לענין \u0003קרבן, אבל מלקות חיובי\u0004 \u0005[לחייב]\u0006 הוא \u0003מחייב,\u0004 ונמצא שיש לדעתו, אף בשבועות, שתים שהן ארבע — לענין מלקות. ומנין שיש איסור על שבועה לשעבר, לחייב עליה מלקות?","\u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: בפירוש ריבתה תורה שבועת שקר דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שבועת שוא,\u0004 כגון הנשבע על עץ שהוא אבן, ללמדנו שלוקים גם עליה, ויש לומר כי \u0003מה\u0004 שבועת \u0003שוא\u0004 היא שבועה \u0003לשעבר,\u0004 על דבר המצוי כבר — \u0003אף\u0004 שבועת \u0003שקר\u0004 הכתובה בתורה (\"לא תשבעו בשמי לשקר\". ויקרא יט, יב) \u0003נמי\u0004 \u0005[גם כן]\u0006 עובר עליה גם \u0003לשעבר.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה שנשבע \u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 לוקה — \u0003כ\u0004דברי \u0003רבא,\u0004 מריבוי הכתוב. נשבע \u0003\"שלא אוכל\" ואכל, נמי\u0004 \u0005[גם כן]\u0006 לוקה שכן \u0003לאו שיש בו מעשה הוא,\u0004 שאכל. \u0003אלא\u0004 נשבע \u0003\"אוכל\" ולא אכל, אמאי\u0004 \u0005[מדוע]\u0006 לוקה? הרי \u0003לאו שאין בו מעשה הוא,\u0004 שהימנעות מאכילה אינה מעשה, ואין לוקים עליו!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' ישמעאל\u0004 כי גם \u0003לאו שאין בו מעשה לוקין עליו.\u0004","ומתקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את המשנה, כשיטת ר' ישמעאל, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדבריו של \u0003ר' יוחנן\u0004 על דבריו של \u0003ר' יוחנן,\u0004 שמצד אחד","\u0003אמר ר' יוחנן: הלכה כסתם משנה,\u0004 ואם כן צריך הוא לפסוק כסתם משנתנו, שעולה ממנה שאף לאו שאין בו מעשה לוקים עליו.","\u0003ואתמר\u0004 \u0005[ו\u0006מצד אחר \u0005נאמר]\u0006 כך: מי שנשבע \u0003\"שבועה שאוכל ככר זו היום\", ועבר היום ולא אכלה, ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003אינו לוקה.\u0004 אלא שנחלקו בטעם הדבר, \u0003ר' יוחנן אמר: אינו לוקה, משום דהוה\u0004 \u0005[שהוא]\u0006 \u0003לאו שאין בו מעשה\u0004 שהרי מה שלא אכל הוא רק הימנעות ולא עשיה, \u0003וכל לאו שאין בו מעשה אין לוקין עליו. וריש לקיש אמר: אינו לוקה,\u0004 משום שכאשר מתרים בו לקיים את שבועתו, ואם לא — ייענש, \u0003התראת ספק היא,\u0004 שגם אם אין כוונתו לאכול יש לו זמן לחזור בו ולאכול, \u0003והתראת ספק לא שמה התראה!\u0004","ומשיבים: \u0003ר' יוחנן סתמא אחרינא אשכח\u0004 \u0005[סתם\u0006 משנה \u0005אחרת מצא]\u0006 שממנה מוכח שלאו שאין בו מעשה אין לוקים עליו, ולפיה פסק, בניגוד למשנה שלנו.","ושואלים: \u0003הי סתמא\u0004 \u0005[איזו סתם\u0006 משנה\u0005]\u0006 מצא? \u0003אילימא האי סתמא\u0004 \u0005[אם תאמר סתם\u0006 משנה \u0005זו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו]\u0006 בענין קרבן הפסח: \u0003אבל המותיר\u0004 מן הבשר עד בוקר חמישה עשר בניסן, \u0003ב\u0004פסח ה\u0003טהור, והשובר\u0004 עצם \u0003ב\u0004קרבן פסח ה\u0003טמא\u0004 — \u0003אינו לוקה את הארבעים.\u0004","ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שובר בטמא\u0004 אינו לוקה — \u0003דכתיב\u0004 \u0005[\u0006משום \u0005שנאמר]\u0006 בקרבן הפסח: \u0003\"ועצם לא תשברו בו\"\u0004 (שמות יב, מו), ויש לדייק: \"בו\" — \u0003בכשר ולא בפסול. אבל המותיר בטהור מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינו לוקה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהוי\u0004 \u0005[שהוא]\u0006 \u0003לאו שאין בו מעשה, וכל לאו שאין בו מעשה אין לוקים עליו?\u0004 ומכאן למד ר' יוחנן.","על כך יש להקשות: \u0003וממאי\u0004 \u0005[ומנין]\u0006 שמשנה זו הפוטרת את המותיר ממלקות שיטת \u0003ר' יעקב היא,\u0004 ש\u0003אמר: לאו שאין בו מעשה אין לוקין עליו? דלמא\u0004 \u0005[שמא]\u0006 המשנה כשיטת \u0003ר' יהודה היא, ו\u0004שלדעתו המותיר מן הפסח אינו לוקה מטעם אחר, \u0003משום\u0004 ש\u0003בא הכתוב ליתן עשה אחר לא תעשה\u0004 זה, כדי לתקן מה שעבר, \u0003הא לאו הכי\u0004 — \u0003לקי\u0004 \u0005[הרי אם לא כך\u0006 — היה \u0005לוקה]\u0006 למרות שאין בו מעשה!","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין זה: \u0003\"לא תותירו ממנו עד בקר והנתר ממנו עד בקר באש תשרפו\"\u0004 (שמות יב, י), \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 (\"והנותר... באש תשרופו\") \u0003אחר לא תעשה\u0004 (\"לא תותירו\"), \u0003לומר שאין לוקין עליו\u0004 על הלא תעשה, שכל לאו שיש עשה אחריו לתקנו — אין לוקים עליו, \u0003דברי ר' יהודה. ר' יעקב אומר: לא מן השם הוא זה,\u0004 לא זה הוא הטעם, \u0003אלא משום דהוה\u0004 \u0005[שהוא]\u0006 \u0003לאו שאין בו מעשה, ולאו שאין בו מעשה אין לוקים עליו.\u0004 ואם כן, מנין למד ר' יוחנן שלאו שאין בו מעשה אין לוקים עליו?","\u0003אלא האי סתמא אשכח\u0004 \u0005[סתם\u0006 משנה \u0005זו מצא]\u0006 ר' יוחנן, בהמשך מסכת זו, וממנה למד שאין לוקים על לאו שאין בו מעשה: נשבע \u0003\"שבועה שלא אוכל ככר זו\",\u0004 וחזר ונשבע: \u0003\"שבועה שלא אוכלנה\", ואכלה\u0004 —"],["\u0003אינו חייב אלא אחת,\u0004 שאין שבועה חלה על שבועה. \u0003זו היא שבועת ביטוי\u0004 (\"נפש כי תשבע לבטא בשפתים\". ויקרא ה, ד) \u0003שחייבין על זדונה מכות ועל שגגתה קרבן עולה ויורד.\u0004","ויש לדייק בלשון: \u0003זו\u0004 דווקא \u0003היא\u0004 שבועה ש\u0003חייבין על זדונה מכות,\u0004 שנשבע \"שלא אוכל\" ואכלה, \u0003אבל\u0004 נשבע \u0003\"אוכל\" ולא אכל\u0004 — \u0003לא לקי\u0004 \u0005[לוקה],\u0006 משום שאין בו מעשה. ועל פי סתם משנה זו פסק ר' יוחנן (שלא כסתם משנתנו).","ושואלים: \u0003מכדי האי סתמא והאי סתמא\u0004 \u0005[הרי זו סתם\u0006 משנה \u0005וזו סתם\u0006 משנה\u0005],\u0006 \u0003מאי חזי דעביד כי האי סתמא, לעביד כי האי סתמא\u0004 \u0005[מה ראה\u0006 ר' יוחנן \u0005שעשה כאותה סתם\u0006 משנה, \u0005שיעשה כסתם זו\u0006 משנה שלנו\u0005]?\u0006","ומשיבים: \u0003ולטעמיך רבי גופיה, היכי סתם לן הכא הכי והכא הכי\u0004 \u0005[ולטעמך,\u0006 לשיטתך, \u0005רבי עצמו,\u0006 כשסידר את המשנה, \u0005איך סתם לנו כאן כך וכאן כך,\u0006 וסתר דברי עצמו\u0005]?\u0006","\u0003אלא מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר\u0004 רבי כי \u0003לאו שאין בו מעשה לוקין עליו, וסתמה\u0004 (סתם כדעה זו) במשנתנו, \u0003והדר\u0004 \u0005[וחזר]\u0006 ו\u0003סבר\u0004 שלאו שאין בו מעשה \u0003אין לוקין עליו, וסתמה\u0004 במשנה להלן, \u0003ו\u0004מכל מקום \u0003משנה\u0004 ראשונה, ששנה קודם שחזר בו, \u0003לא זזה ממקומה,\u0004 לא נשתנה נוסחה, אלא נשארה כפי שנשנתה מתחילה.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת אותה,\u0006 את המשנה\u0005]\u0006 ששנינו לענין שבועות שתים שהן ארבע — \u0003כר' ישמעאל ול\u0004ענין \u0003מלקות,\u0004 אולם אם מפרשים כך את המשנה, יש לשאול: \u0003מראות נגעים מאי\u0004 \u0005[מה]\u0006 \u0003מלקות איכא\u0004 \u0005[יש]\u0006 בהם? ומשיבים: \u0003ב\u0004מי ש\u0003קוצץ בהרתו,\u0004 שנאמר \"השמר בנגע הצרעת\" (דברים כד, ח), \u0003וכ\u0004דברי \u0003ר' אבין אמר ר' אילעא,\u0004 ש\u0003אמר ר' אבין אמר ר' אילעא: כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו לשון \u0003\"השמר\", \"פן\" ו\"אל\" אינו אלא\u0004 מצות \u0003לא תעשה\u0004 שלוקים עליה, ולמדו חכמים ש\"השמר בנגע הצרעת\" עניינו מצוות לא תעשה, שלא לקצוץ או לפגום את הנגע, אלא להראותו לכהן כמות שהוא. והקוצץ בהרתו, הרי זה לוקה ככל העובר על לאו שיש בו מעשה.","ועוד שואלים: \u0003יציאות שבת מאי\u0004 \u0005[מה]\u0006 \u0003מלקות איכא\u0004 \u0005[יש]\u0006 בהם? והרי איסור הוצאה בשבת \u0003לאו שניתן לאזהרת מיתת בית דין הוא,\u0004 שנכתב בתורה כדי להתרות ולהעניש על ידו במיתה, שהרי המחלל שבת דינו בסקילה, \u0003ו\u0004כלל הוא: \u0003כל לאו שניתן לאזהרת מיתת בית דין אין לוקין עליו!\u0004 ומשיבים: \u0003משום הכי קא מוקמינא\u0004 \u0005[משום כך אני מעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003כר' ישמעאל, דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003לאו שניתן לאזהרת מיתת בית דין לוקין עליו.\u0004","ומקשים: מתשובה זו משמע כי \u0003הא לאו הכי\u0004 \u0005[אבל\u0006 אם \u0005לא כך],\u0006 לולא קושי זה, \u0003קיימא\u0004 \u0005[עומדת\u0006 משנתנו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא,\u0004 שהוא סבור שאין לוקים על לאו כזה? והרי גם לשיטתו \u0003קשיא\u0004 \u0005[קשה]\u0006 ענין \u0003ידיעות\u0004 הטומאה, שכאמור לעיל, הוא אינו סבור כמשנתנו, שעל העלם מקדש חייב קרבן! ומשיבים: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמרת\u0004 בגלל קושי דומה, בענין שבועות, שמשנתנו שיטת \u0003ר' ישמעאל היא ול\u0004ענין \u0003מלקות?\u0004 כך יש לפרשה לשיטת \u0003ר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003ול\u0004ענין \u0003מלקות.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע השתמשה כאן המשנה בלשון \u0003\"ידיעות\u0004 הטומאה\"? \u0003\"התראות\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי עונש המלקות תלוי לא בידיעה של האיסור, אלא בהתראה שמתרים בו באדם שהוא עתיד ללקות עליו! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 לדרך זו: \u0003\"ידיעות\u0004 של \u0003התראות\",\u0004 שהוא יודע שהוא עובר על איסור ועתיד ללקות, כשמתרים בו.","ומקשים עוד: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה מפרש את משנתנו לענין מלקות, מדוע שנה \u0003\"שתים שהן ארבע\"? תרתי הוא דהויין\u0004 \u0005[שתים,\u0006 שתי התראות בלבד \u0005הוא שישנן]!\u0006 שהרי כשמתרים בו מפרשים לו גם ענין הטומאה וגם ענין הקודש או המקדש, ואין כאן אלא שני עונשי מלקות, על טומאת הקודש ועל טומאת המקדש! \u0003ותו\u0004 \u0005[ועוד],\u0006 מה ששנינו בהמשך המשנה בענין זה: \u0003את שיש בה ידיעה בתחלה וידיעה בסוף והעלם בינתים, העלמה למלקות מאי עבידתיה\u0004 \u0005[מה היא עושה]?\u0006 הרי אדם מתחייב מלקות רק מתוך התראה וידיעה! \u0003ותו\u0004 \u0005[ועוד],\u0006 הרי שנינו במפורש במשנה: \u0003הרי זה ב\u0004קרבן \u0003עולה ויורד,\u0004 ולא לענין מלקות! וקשה איפוא מאד להעמיד חלק ממשנתנו לענין מלקות. אך מצד אחר תמוה שמשנתנו אינה לא כשיטת ר' ישמעאל ולא כשיטת ר' עקיבא.","\u0003אלא אמר רב יוסף:\u0004 משנתנו כשיטת \u0003רבי\u0004 (יהודה הנשיא) \u0003היא, ונסיב לה אליבא דתנאי\u0004 \u0005[ולקח,\u0006 שנה \u0005אותה כשיטת תנאים\u0006 שונים\u0005].\u0006 \u0003בידיעות נסיב לה\u0004 \u0005[לקח,\u0006 שנה \u0005אותה]\u0006 \u0003כר' ישמעאל, בשבועות נסיב לה\u0004 \u0005[לקח,\u0006 שנה \u0005אותה]\u0006 \u0003כר' עקיבא.\u0004","\u0003אמר רב אשי: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי לשמועה זו\u0006 של רב יוסף \u0005לפני]\u0006 \u0003רב כהנא. ואמר לי: לא תימא\u0004 \u0005[אל תאמר]\u0006 אל תפרש את דבריו של רב יוסף, ש\u0003רבי נסיב לה אליבא דתנאי\u0004 \u0005[לקח,\u0006 שנה \u0005אותה כשיטת תנאים\u0006 שונים\u0005]\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[והוא\u0006 עצמו \u0005אינו סבור כך],\u0006","\u0003אלא רבי טעמיה דנפשיה\u0004 \u0005[שיטת\u0006 וסברת \u0005עצמו]\u0006 \u0003מפרש\u0004 ולשיטתו יש חיוב בנשבע על העבר, וכן יש חיוב בהעלם מקדש. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין שאינו חייב\u0004 בקרבן על טומאת מקדש וקדשיו \u0003אלא על\u0004 עבירה \u0003שיש בה ידיעה בתחלה וידיעה בסוף והעלם בינתים? תלמוד לומר: \"ונעלם\" \"ונעלם\" שני פעמים, דברי ר' עקיבא.\u0004 שכך נאמר בתורה בענין זה: \"או נפש אשר תגע בכל דבר טמא... ונעלם ממנו והוא טמא... או כי יגע בטומאת אדם... ונעלם ממנו והוא ידע...\" (ויקרא ה, ב— ג). ויש להבין כי מפני שכתובה העלמה פעמיים, היתה ידיעה בין שתי העלמות אלה.","\u0003רבי אומר: אינו צריך\u0004 להוכחה זו, אלא \u0003הרי הוא אומר\u0004 באותו פסוק:"],["\"או כי יגע בטומאת אדם וכו' ונעלם ממנו והוא ידע ואשם\" (ויקרא ה, ג), \u0003\"ונעלם\u0004 ממנו\" — \u0003מכלל\u0004 הדברים משמע שקודם לכן \u0003ידע,\u0004 ולכן נאמר שנעלם ממנו, ולפי זה מה שנאמר \u0003\"והוא ידע\"\u0004 — \u0003הרי כאן שתי ידיעות,\u0004 אחת קודם שנעלם ממנו ואחת לאחר מכן, ומכאן אנו למדים שצריך להיות העלם באמצע. \u0003אם כן מה תלמוד לומר \"ונעלם\" \"ונעלם\"\u0004 פעמיים — \u0003לחייב על העלם טומאה\u0004 שלא ידע שהוא טמא, \u0003ו\u0004גם \u0003על העלם מקדש\u0004 שלא ידע שנכנס למקדש, הרי שפסק כר' ישמעאל, אבל מטעמו שלו.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003ב\u0004ענין \u0003ידיעות\u0004 הטומאה \u0003דאית ליה טעמיה דנפשיה\u0004 \u0005[שיש לו\u0006 לרבי \u0005טעם,\u0006 שיטה, \u0005שלו עצמו]\u0006 שלא כדעת ר' עקיבא, אבל לענין \u0003שבועות, דלית ליה טעמיה דנפשיה\u0004 \u0005[שאין לו טעם,\u0006 שיטה \u0005של עצמו]\u0006 אלא הולך הוא בשיטת ר' עקיבא, \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003סברא הוא.\u0004","\u0003(לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 יש לשאלה זו: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003בידיעות\u0004 הטומאה \u0003דסבר לה\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003כר' ישמעאל, בשבועות דסבר לה\u0004 \u0005[שהוא סבור]\u0006 \u0003כר' עקיבא, מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003סברא הוא):\u0004","\u0003ר' עקיבא מאי טעמא קא\u0004 \u0005[מה טעם הוא]\u0006 \u0003מחייב\u0004 על שבועה \u0003לשעבר\u0004 — \u0003דדריש ריבויי ומיעוטי\u0004 \u0005[\u0006משום \u0005ש\u0006הוא \u0005דורש\u0006 את הכתובים בדרך של \u0005ריבויים ומיעוטים],\u0006 כמבואר להלן (שבועות כו,א), \u0003רבי נמי דריש ריבויי ומיעוטי\u0004 \u0005[גם כן דורש\u0006 את המקרא בדרך של \u0005ריבויים ומיעוטים],\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: בכל\u0004 דבר ששוויו חמישה שקלים \u0003פודין בכור אדם, חוץ מן השטרות. ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 \u0003בכל פודין בכור אדם, חוץ מעבדים ושטרות וקרקעות.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי? דריש ריבויי ומיעוטי\u0004 \u0005[ש\u0006הוא \u0005דורש\u0006 בדרך של \u0005ריבויים ומיעוטים],\u0006 שנאמר לכהנים: \"ופדויו מבן חודש תפדה בערכך כסף חמשת שקלים בשקל הקודש\" (במדבר יח, טז), וכך הוא דורש: \u0003\"ופדויו מבן חדש\"\u0004 — \u0003ריבה,\u0004 שלשון כללית זו מלמדת שניתן לפדותו בכל דבר שהוא, \u0003\"בערכך כסף חמשת שקלים\"\u0004 — \u0003מיעט,\u0004 לומר: דווקא בכסף. ובלשון הכללית \u0003\"תפדה\"\u0004 — \u0003חזר וריבה,\u0004 הרי","\u0003ריבה ומיעט וריבה\u0004 — \u0003ריבה הכל,\u0004 חוץ מדבר אחד שנתמעט. \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ריבה\u0004 — \u0003כל מילי\u0004 \u0005[הדברים],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 — \u0003מיעט שטרות,\u0004 שאין פודים בהם, לפי שהם עצמם אינם כסף, ואינם שווה כסף אמיתי, אלא רק משמשים לראיה או לקניה של דבר אחר. זו שיטתו של רבי.","\u0003ורבנן דרשי כללי ופרטי\u0004 \u0005[וחכמים\u0006 החולקים עליו \u0005דורשים\u0006 את הכתובים בדרך של \u0005כללים ופרטים],\u0006 כיצד? \u0003\"ופדויו מבן חדש\"\u0004 — \u0003כלל, \"בערכך כסף חמשת שקלים\"\u0004 — \u0003פרט, \"תפדה\"\u0004 — \u0003חזר וכלל,\u0004","\u0003כלל ופרט וכלל\u0004 — \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט: מה הפרט\u0004 (חמשת שקלים) \u0003מפורש,\u0004 שהוא \u0003דבר המטלטל וגופו\u0004 (והוא עצמו) \u0003ממון\u0004 — \u0003אף כל דבר המטלטל וגופו ממון\u0004 ניתן לפדות בו. \u0003יצאו\u0004 מכלל זה \u0003קרקעות,\u0004 שלא ניתן לפדות בהם לפי \u0003שאינן מטלטלין, יצאו\u0004 גם \u0003עבדים,\u0004 למרות שהם מיטלטלים, משום \u0003שהוקשו\u0004 (הושוו) בדינם \u0003לקרקעות\u0004 להרבה עניינים. \u0003יצאו שטרות,\u0004 ש\u0003אף על פי ש\u0004הם \u0003מטלטלין אין גופן ממון,\u0004 שאין להם ערך עצמי, ואינם משמשים אלא לראיה או לקניה של דבר אחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לאמימר:\u0004 וכי \u0003רבי דריש ריבויי ומיעוטי\u0004 \u0005[דורש\u0006 את הכתובים ב\u0005ריבויים ומיעוטים]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 מצאנו ש\u0003רבי כללי ופרטי דריש\u0004 \u0005[כללים ופרטים\u0006 הוא \u0005דורש]!\u0006","\u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 בענין עבד עברי הרוצה להישאר בעבדותו לאחר שש שנים, שנאמר: \"ולקחת את המרצע ונתתה באוזנו ובדלת\" (דברים טו, יז) וכך דרשו: \u0003\"מרצע\"\u0004 — \u0003אין לי אלא מרצע\u0004 בלבד, \u0003מנין לרבות הסול\u0004 (קוץ דקל) \u0003והסירה\u0004 (קוץ), \u0003המחט והמקדח והמכתב\u0004 (חרט, כלי לכתיבה על גבי שעווה)? \u0003תלמוד לומר \"ולקחת\"\u0004 — \u0003כל דבר שנלקח ביד, דברי ר' יוסי בר' יהודה. רבי אומר: \"מרצע\"\u0004 — \u0003מה מרצע מיוחד\u0004 שהוא \u0003של מתכת, אף כל של מתכת,\u0004 אבל בדבר שאינו עשוי מתכת לא ניתן לרצוע עבד עברי.","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 באיזה ענין \u0005הם חולקים]?\u0006 \u0003רבי דריש כללי ופרטי\u0004 \u0005[דורש כללים ופרטים],\u0006 \u0003ור' יוסי בר' יהודה דריש\u0004 \u0005[דורש]\u0006"],["\u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים]!\u0006","ומשיבים: \u0003אין, בעלמא כללי ופרטי דריש\u0004 \u0005[כן, ב\u0006דרך \u0005כלל כללים ופרטים דורש\u0006 רבי\u0005],\u0006 \u0003והכא היינו טעמא\u0004 \u0005[וכאן,\u0006 לענין פדיון הבן, \u0005זהו הטעם]\u0006 שהוא דורש בדרך של ריבוי ומיעוט — \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל.\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בענין סימני דגים טהורים: מה שנאמר \u0003\"במים\" \"במים\" שני פעמים,\u0004 תחילה בלשון כללית \"את זה תאכלו מכל אשר במים כל אשר לו סנפיר וקשקשת במים\" (ויקרא יא, ט), ולאחר מכן מופיע הפרט \"בימים ובנחלים\", \u0003אין זה כלל ופרט\u0004 כלומר, אין דורשים אותו בדרך של \"כלל ופרט וכלל\" (כדרכו של ר' ישמעאל לדרוש), מפני שהפרט אינו מופיע בכתוב בין שני הכללים, \u0003אלא\u0004 דורשים אותו בדרך של \u0003ריבה\u0004 הכתוב \u0003ומיעט.\u0004 והוא הדין לדעת רבי לענין פדיון הבן, הואיל ושני הכללים מופיעים בכתוב לפני הפרט (\"ופדויו... תפדה... כסף חמשת שקלים\" דברים יח, טז) הרי יש לדרוש את הכתוב בדרך של ריבוי ומיעוט, ולא בדרך של כלל ופרט.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על רבי, ודורשים כתוב זה בדרך של כלל ופרט, מה הם סבורים? \u0003אמר רבינא: כדאמרי במערבא\u0004 \u0005[כמו שאומרים\u0006 החכמים \u0005בארץ ישראל]\u0006 בענין זה: \u0003כל מקום שאתה מוצא שתי כללות הסמוכות זה לזה\u0004 — \u0003הטל\u0004 את ה\u0003פרט\u0004 שאינו מופיע ביניהם \u0003ביניהן, ודונם\u0004 (ודון אותם) \u0003ב\u0004דרך של \u0003כלל ופרט,\u0004 כאילו היה זה כלל ופרט וכלל.","ומתקשים: \u0003השתא דאמרת רבי כללי ופרטי דריש\u0004 \u0005[עכשיו שאתה אומר\u0006 ש\u0005רבי כללים ופרטים\u0006 הוא \u0005דורש]\u0006 כדרכו של ר' ישמעאל, \u0003בעל כורחיך קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003שבועות,\u0004 שהוא שונה במשנתנו שלא כשיטתו, אלא כר' עקיבא, שדורש דין זה מריבוי ומיעוט! \u0003אלא\u0004 יש לחזור ממה שהסביר רב כהנא לעיל, שהמשנה מביאה את שיטתו של רבי עצמו, שבענין ידיעות הטומאה הוא סבור כר' ישמעאל (אך מטעמו שלו) ובדבר אחד הוא הולך כשיטת ר' עקיבא. אלא יש לומר כי בענין \u0003שבועות נסיב אליבא\u0004 \u0005[הוא לוקח,\u0006 שונה במשנה, \u0005לפי שיטתו]\u0006 של \u0003ר' עקיבא, וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא\u0006 עצמו \u0005אינו סבור כן],\u0006 שהרי הוא דורש בכלל ופרט, כר' ישמעאל.","ושבים לדון בברייתא שהובאה לעיל \u0003גופא\u0004 \u0005[לגופה],\u0006 ששנינו: \u0003מנין שאינו חייב\u0004 קרבן עולה ויורד על כניסה למקדש או על אכילת קודש כשהוא טמא, \u0003אלא על\u0004 טומאה \u0003שיש בה ידיעה בתחלה וידיעה בסוף והעלם בינתים? תלמוד לומר\u0004 בפרשה זו \u0003\"ונעלם\" \"ונעלם\" שני פעמים\u0004 (ויקרא ה, ב— ג), \u0003דברי ר' עקיבא.\u0004","\u0003רבי אומר: אינו צריך\u0004 ללימוד זה, שכן \u0003הרי הוא אומר\u0004 \"או כי יגע בכל טומאת אדם וכו' ונעלם ממנו והוא ידע ואשם\" (ויקרא ה, ג), \u0003\"ונעלם\u0004 ממנו\" — \u0003מכלל\u0004 הדברים שקודם לכן \u0003ידע, \"והוא ידע\"\u0004 — \u0003הרי כאן שתי ידיעות,\u0004 אחת קודם שנעלם ממנו ואחת לאחר מכן, \u0003אם כן מה תלמוד לומר \"ונעלם\" \"ונעלם\"\u0004 שני פעמים? הרי זה בא להוסיף ענין אחר — \u0003לחייב על העלם טומאה\u0004 כשלא ידע שהוא טמא, \u0003ו\u0004גם \u0003על העלם מקדש\u0004 כשלא ידע שנכנס למקדש.","ומבררים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 רבי: \u0003\"ונעלם\"\u0004 — \u0003מכלל שידע\u0004 קודם לכן על טומאה זו. ושואלים: \u0003מאי משמע\u0004 \u0005[כיצד נשמע\u0006 הדבר מן הכתוב\u0005]?\u0006 \u0003אמר רבא: מ\u0004מה ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"והיא עלומה ממנו\",\u0004 שאינו יודע כלל על קיומה, אלא שרק עכשיו נעלם ממנו דבר שידעו כבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 שכך אתה מסביר את משמעות המלה \"ונעלם\", \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003סוטה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ושכב איש אותה... \u0003ונעלם מעיני אישה\"\u0004 (במדבר ה, יג), יש להבין כמו כאן — \u0003מכלל דהוי ידע\u0004 \u0005[שהיה יודע\u0006 קודם לכן\u0005]\u0006 שאשתו מזנה תחתיו; ואולם \u0003מעיקרא אי הוה ידע מי בדקו לה מיא\u0004 \u0005[אם היה יודע מתחילה\u0006 שאשתו מזנה תחתיו ולא עשה כלום, \u0005האם בודקים אותה המים]?\u0006","\u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק \u0003\"ונקה האיש מעון והאשה ההוא תשא את עונה\"\u0004 (במדבר ה, לא): \u0003בזמן שהאיש מנוקה מעון\u0004 — \u0003המים בודקין את אשתו, אין האיש מנוקה מעון\u0004 — \u0003אין המים בודקין את אשתו.\u0004 ואיש זה שידע שזנתה אשתו ונאסרה עליו, ולמרות זאת לא גירשה — אינו נקי מעוון!","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003תורה, דכתיב\u0004 \u0005[שנאמר\u0006 עליה\u0005]:\u0006 \u0003\"ונעלמה מעיני כל חי ומעוף השמים נסתרה\"\u0004 (איוב כח, כא), \u0003מכלל\u0004 הדברים יש להבין לשיטתך \u0003דאיכא דהוה ידע ביה\u0004 \u0005[שיש\u0006 מי \u0005שהיה\u0006 \u0005יודע בה\u0006 קודם לכן\u0005];\u0006 \u0003והכתיב\u0004 \u0005[ו\u0006אולם \u0005הרי נאמר]\u0006 בה: \u0003\"לא ידע אנוש ערכה\u0004 ולא תמצא בארץ החיים\" (איוב כח, יג)!","\u0003אלא אמר אביי:\u0004 אין כוונת רבי לומר שמשמעות \"ונעלם\" היא שאותו אדם ידע קודם לכן מה שאינו יודע כעת, אלא \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רבי: ידיעת בית רבו,\u0004 מה שלמד כל אדם מישראל בהיותו בבית רבו, שאסור להיכנס למקדש כשהוא טמא, \u0003שמה\u0004 (נחשבת) \u0003ידיעה,\u0004 ולדעת רבי די בידיעה מוקדמת זאת כדי לחייבו קרבן. והוא פירוש מה שאמר \"מכלל שידע\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא\u0004 להסבר זה, \u0003דקתני\u0004 \u0005[\u0006מה \u0005שהוא שונה\u0006 במשנתנו\u0005]\u0006 מקרה ש\u0003אין בה ידיעה בתחלה ויש בה ידיעה בסוף, מי איכא דלית ליה\u0004 \u0005[האם יש מי שאין לו]\u0006 \u0003ידיעת בית רבו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, משכחת לה\u0004 \u0005[כן, מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 \u0003בתינוק שנשבה לבין הגוים\u0004 ולא למד מימיו כלל.","שנינו במשנתנו: \u0003יציאות שבת שתים שהן ארבע.\u0004 ומביאים, \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה במסכת שבת\u0005]:\u0006 \u0003יציאות שבת שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ.\u0004 ושואלים: \u0003מאי שנא הכא דתנא\u0004 \u0005[מה שונה כאן,\u0006 במשנתנו, \u0005ששנה]\u0006 \u0003\"שתים שהן ארבע\", ותו לא\u0004 \u0005[ולא יותר],\u0006 \u0003ומאי שנא התם דתני\u0004 \u0005[ומה שונה שם\u0006 במסכת שבת \u0005ש\u0006התנא \u0005שונה]\u0006 בהרחבה: \u0003שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ?\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 ש\u0003עיקר\u0004 הלכות \u0003שבת הוא, תני\u0004 \u0005[\u0006הריהו \u0005שונה]\u0006 גם את \u0003אבות\u0004 המלאכה האסורה, המפורשים בתורה, שהם ההוצאה מרשות היחיד לרשות הרבים, על ידי העומד ברשות היחיד ועל ידי העומד ברשות הרבים, \u0003ו\u0004גם \u0003תולדות\u0004 המלאכה, שאינם כתובים בתורה, שהם ההכנסה מרשות הרבים לרשות היחיד על ידי זה ועל ידי זה. \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003עיקר\u0004 הלכות \u0003שבת הוא\u0004 — \u0003אבות תני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 \u0003ותולדות לא תני\u0004 \u0005[אינו שונה].\u0006","ומקשים: \u0003אבות מאי נינהו\u0004 \u0005[מה הם]?\u0006 \u0003יציאות\u0004 (הוצאות מרשות היחיד לרשות הרבים), והרי \u0003יציאות תרתי הויין\u0004 \u0005[שתים הן],\u0006 של העומד בפנים ושל העומד בחוץ, ובמשנתנו שנינו שהן ארבע!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאכן מדובר כאן ביציאות, אך לא רק אלו שחייבים עליהן, אלא \u0003מהן לחיוב ומהן לפטור,\u0004 שיש מקרים בהם אדם מוציא מרשות היחיד לרשות הרבים ואינו מתחייב על כך, כגון שלא עשה את ההוצאה בשלימות (עקירה מרשות היחיד והנחה ברשות הרבים), \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003מראות נגעים\u0004 שהוזכרו אף הם במשנה באותה לשון (\"שנים שהם ארבעה\") \u0003קתני\u0004 \u0005[הוא שונה],\u0006 \u0003מה התם כולהו לחיובא אף הכא כולהו לחיובא\u0004 \u0005[מה שם כולם,\u0006 כל הארבעה, הם \u0005לחיוב, אף כאן,\u0006 לענין שבת, \u0005כולם לחיוב]!\u0006","\u0003אלא אמר רב פפא: התם\u0004 \u0005[שם,\u0006 במסכת שבת\u0005]\u0006 שהוא \u0003עיקר\u0004 הלכות \u0003שבת, תני חיובי ופטורי\u0004 \u0005[\u0006הוא \u0005שונה\u0006 גם את \u0005החיובים ו\u0006גם את \u0005הפטורים],\u0006 \u0003הכא חיובי תני ופטורי לא תני\u0004 \u0005[כאן,\u0006 במשנתנו, את \u0005החיובים\u0006 הוא \u0005שונה ו\u0006את \u0005הפטורים אינו שונה].\u0006","ומקשים: \u0003חיובי מאי נינהו\u0004 \u0005[חיובים מה הם]\u0006 — \u0003יציאות,\u0004 והרי \u0003יציאות תרתי הוא דהויין\u0004 \u0005[הריהן שתים],\u0006 ולא ארבע, כפי ששנינו במשנתנו! ומשיבים: הכוונה במשנתנו היא ל\u0003שתים\u0004 של \u0003הוצאה ושתים\u0004 של \u0003הכנסה,\u0004 שגם על ההכנסה מרשות הרבים לרשות היחיד מתחייבים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"יציאות\" קתני\u0004 \u0005[הוא שונה]\u0006 במשנה, ואינו מזכיר כלל הכנסה! \u0003אמר רב אשי:\u0004 ה\u0003תנא, הכנסה נמי\u0004 \u0005[גם כן]\u0006 \u0003\"הוצאה\" קרי\u0004 \u0005[\u0006הוא \u0005קורא]\u0006 \u0003לה. ממאי\u0004 \u0005[מניין]\u0006 שכן הוא?"],["\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 במסכת שבת במנין המלאכות: \u0003המוציא מרשות לרשות חייב; מי לא עסקינן דקא מעייל עיולי\u0004 \u0005[האם אין אנו עוסקים\u0006 גם במקרה \u0005שהוא מכניס\u0006 מרשות הרבים לרשות היחיד\u0005],\u0006 \u0003וקא קרי ליה\u0004 \u0005[והוא קורא לו]\u0006 \u0003\"הוצאה\".\u0004","ודוחים: \u0003ודלמא קא מפיק\u0004 \u0005[ושמא\u0006 מדובר דווקא כש\u0005הוא מוציא]\u0006 \u0003מרשות היחיד לרשות הרבים!\u0004 ומשיבים: \u0003אם כן, ניתני\u0004 \u0005[שישנה]:\u0006 \u0003\"המוציא מרשות היחיד לרשות הרבים\", מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הלשון הסתמית \u0003\"מרשות לרשות\"\u0004 — לומר שכן הוא בכל מקרה, \u0003אפילו מרשות הרבים לרשות היחיד,\u0004","\u0003וקא קרי\u0004 \u0005[והוא קורא]\u0006 \u0003לה ,הוצאה\".\u0004 ומסבירים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מהו]?\u0006 ה\u0003תנא כל עקירת חפץ ממקומו \"הוצאה\" קרי\u0004 \u0005[הוא קורא]\u0006 \u0003לה.\u0004","\u0003אמר רבינא: מתניתין נמי דיקא\u0004 \u0005[משנתנו,\u0006 במסכת שבת, \u0005גם כן מדוייקת]\u0006 כהסבר זה, \u0003דקתני\u0004 \u0005[שהוא שונה\u0006 בה\u0005]:\u0006 \u0003יציאות שבת שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ, וקא\u0004 \u0005[והוא]\u0006 \u0003מפרש\u0004 בהמשכה גם מקרים של \u0003הכנסה,\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006 שכן הוא\u0005].\u0006","\u0003רבא אמר:\u0004 יש לפרש את משנתנו באופן אחר, \u0003רשויות קתני\u0004 \u0005[הוא שונה],\u0006 \u0003רשויות שבת שתים,\u0004 רשות הרבים ורשות היחיד, שיש בהן ארבעה חיובים, שנים של הוצאה ושנים של הכנסה.","שנינו במשנתנו: \u0003מראות נגעים שנים שהן ארבעה.\u0004 ומביאים, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת נגעים\u0005]:\u0006 \u0003מראות נגעים שנים שהן ארבעה: בהרת\u0004 הכתובה בתורה — \u0003עזה\u0004 בצבעה הלבן \u0003כשלג, שניה לה\u0004 (התולדה שלה) — לבנה \u0003כסיד ההיכל.\u0004","\u0003שאת\u0004 הכתובה בתורה — לבנה \u0003כצמר לבן, שניה לה\u0004 — \u0003כקרום ביצה.\u0004","\u0003אמר ר' חנינא: מאן תנא\u0004 \u0005[מי\u0006 ש\u0005שנה\u0006 משנתנו\u0005],\u0006 לפיה מחלקים את \u0003מראות נגעים\u0004 לשתי קבוצות נפרדות של אב ותולדה — הרי זה ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא. דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא, כיון\u0004 ש\u0003אמר\u0004 לגבי ארבעה נגעים אלו: \u0003זו למעלה מזו וזו למעלה מזו,\u0004 מראה בהרת הוא הבהיר ביותר (כשלג), ואחריו השאת (כצמר), אחריו כסיד ההיכל, ואחריו דכקרום הביצה, ואין מראה נגע אחד מצטרף עם האחר לשיעור נגע אלא אם כן הוא סמוך לו בדרגה, \u0003אם כן,\u0004 כשנצרף את שתי השיטות, \u0003טיהרת\u0004 נגע שצבעו כ\u0003סיד היכל מלצרף\u0004 אותו לנגע אחר לשיעור טומאה, שכן","\u0003בהדי מאן ליצרפיה\u0004 \u0005[יחד עם מי נצרף אותו]?\u0006 \u0003ליצרפיה בהדי\u0004 \u0005[\u0006אם נרצה \u0005לצרף אותו יחד עם]\u0006 \u0003בהרת\u0004 — הרי לשיטת ר' עקיבא \u0003איכא\u0004 \u0005[יש]\u0006 \u0003שאת דעדיפא מיניה\u0004 \u0005[שעדיף,\u0006 בהיר, \u0005ממנו]\u0006 שמפריד בינו לבין בהרת, ואין מצרפים אלא נגעים סמוכים בדרגת בהירותם. \u0003ליצרפיה בהדי\u0004 \u0005[\u0006אם נרצה \u0005לצרף אותו יחד עם]\u0006 \u0003שאת,\u0004 שנמצא בדרגה אחת למעלה ממנו — הרי לפי למשנתנו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003תולדה דידיה\u0004 \u0005[שלו]\u0006 \u0003הוא,\u0004 ואם כן לא יוכל להצטרף עמו. אלא בהכרח לפי שיטת ר' עקיבא לבן כסיד אינו תולדה של בהרת, ולכן הוא יכול להצטרף לשאת, שהוא דרגה אחת מתחתיו.","ומתקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכך סבור ר' עקיבא, שרק נגעים סמוכים זה לזה בדרגת בהירותם מצטרפים, יכול היה ר' חנינא להוכיח מ\u0003קרום ביצה נמי\u0004 \u0005[גם כן],\u0006 שכן \u0003בהדי מאן ליצרפיה\u0004 \u0005[יחד עם מי נצרף אותו]?\u0006 \u0003ליצרפיה בהדי\u0004 \u0005[\u0006אם נרצה \u0005לצרף אותו יחד עם]\u0006 \u0003שאת\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003סיד\u0004 ש\u0003עדיף מיניה\u0004 \u0005[ממנו,\u0006 מקרום ביצה\u0005],\u0006 והוא מפריד בינו לבין השאת. \u0003ליצרפיה בהדי\u0004 \u0005[\u0006אם נרצה \u0005לצרף אותו יחד עם]\u0006 \u0003סיד\u0004 — \u0003לאו בר מיניה הוא\u0004 \u0005[אין הוא בן מינו],\u0006 שאינו תולדה שלו, ומדוע הזכיר דווקא סיד?"],["ודוחים: \u0003האי מאי\u0004 \u0005[\u0006דבר \u0005זה מה\u0006 הוא\u0005]?\u0006 כלומר, אין מקום לקושי זה, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בלא\u0004 הקושיה מ\u0003סיד היכל\u0004 — מ\u0003קרום ביצה לא קשיא\u0004 \u0005[קשה],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003קרום ביצה\u0004 הוא \u0003מתתאי\u0004 \u0005[מתחתיו]\u0006 של \u0003שאת\u0004 יותר מדרגה אחת — \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]:\u0006 \u0003\"ולשאת ולספחת\"\u0004 (ויקרא יד, נו), הרי שריבתה התורה \u0003ספחת\u0004 שהיא \u0003טפילה\u0004 (נספחת, נלווית) \u0003ל\u0004נגע ה\u0003שאת,\u0004 ומצטרפת אליו \u0003אף על גב דמנחתא מיניה טובא\u0004 \u0005[אף על פי ש\u0006היא \u0005נמוכה ממנו הרבה\u0006 בדרגת הלובן\u0005].\u0006 \u0003אלא סיד היכל קשיא\u0004 \u0005[קשה],\u0006 שאינו יכול להצטרף לבהרת לשיטת ר' עקיבא, מפני שהוא רחוק ממנה שתי דרגות, ואין ריבוי בכתוב לצירוף זה כמו לצירוף שאת וקרום ביצה! \u0003אלא מחוורתא\u0004 \u0005[מחוור\u0006 הדבר], \u0003מתניתין\u0004 \u0005[משנתנו\u0006 היא\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא.\u0004","ומבררים: \u0003והיכא שמעינן\u0004 \u0005[והיכן שמענו]\u0006 \u0003לר' עקיבא\u0004 שהוא סבור ש\u0003זו למעלה מזו,\u0004 וסיד ההיכל אינו מצטרף לבהרת שרחוקה ממנו שתי דרגות?","\u0003אילימא מהא דתניא\u0004 \u0005[אם נאמר מזו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי, שאל יהושע בנו של ר' עקיבא מר' עקיבא: מפני מה אמרו\u0004 חכמים \u0003מראות נגעים שנים שהן ארבעה\u0004 ופירטו את שמותיהם? \u0003אמר לו\u0004 ר' עקיבא: \u0003ואם לאו, מה יאמרו?\u0004 השיב לו ר' יהושע: \u0003יאמרו\u0004 כל שהוא לבן יותר \u0003מקרום ביצה ולמעלה\u0004 — \u0003טמא!\u0004","\u0003אמר לו\u0004 ר' עקיבא: הוזכרו ארבעה מראות אלו כדי \u0003לומר שמצטרפים זה עם זה,\u0004 כל אחד והסמוך לו בדרגת הלובן. \u0003אמר לו\u0004 ר' יהושע, \u0003ויאמרו: מקרום ביצה ולמעלה טמא, ומצטרפין זה עם זה! אמר לו:\u0004 לכך פירטו את שמותיהם, \u0003לומר לך: כל כהן שאינו בקי בהן\u0004 להבחין בין הסוגים השונים, \u0003ובשמותיהן\u0004 — \u0003אינו רואה\u0004 (אינו רשאי לראות) \u0003את הנגעים\u0004 ולדון בהם. עד כאן הדיון שבין ר' עקיבא ובנו.","הרי שר' יהושע מציע כי לשיטת אביו יאמרו שמקרום ביצה ולמעלה מצטרפים זה עם זה, \u0003ואילו\u0004 שיאמרו \u0003מסיד היכל ולמעלה\u0004 מצטרפים זה עם זה \u0003לא קאמר\u0004 \u0005[אמר],\u0006","ו\u0003מ\u0004מה ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 כך, \u0003שמע מינה דשמיע ליה\u0004 \u0005[למד מכאן ששמע אותו]\u0006 את \u0003ר' עקיבא\u0004 ש\u0003אמר: כולהו לבהדי\u0004 \u0005[כולם יחד עם]\u0006 \u0003שאת מצטרפין,\u0004 קרום ביצה — מפני שנתרבה בכתוב (כמובא לעיל), וסיד היכל — משום שהוא דרגה אחת של לובן מתחתיו. אבל סיד היכל אינו מצטרף עם הבהרת — משום שהשאת מפריד ביניהם בדרגת הלובן.","הוכחה זו יש לדחות: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הציע ר' יהושע: ויאמרו מקרום ביצה ולמעלה מצטרפים זה עם זה, \u0003שאת ותולדתה\u0004 (קרום ביצה) \u0003בהרת ותולדתה\u0004 (סיד היכל), אלא שאמר את הדברים בקיצור. ואין מכאן ראיה שסיד היכל אינו מצטרף עם הבהרת!","\u0003אלא\u0004 מניין אנו יודעים שכך סבור ר' עקיבא — \u0003מ\u0004דבריו של \u0003ר' חנינא,\u0004 ש\u0003אמר ר' חנינא: משל\u0004 להבין את דבריו של \u0003ר' עקיבא,\u0004 שאמר שהנגעים מצטרפים זה עם זה לפי דרגת בהירותם, \u0003למה הדבר דומה? לארבעה כוסות של חלב, אחד נפלו לתוכו שתי טיפין של דם, ואחד נפלו לתוכו ארבע טיפין של דם, ואחד נפלו לתוכו שמונה, ואחד נפלו לתוכו שתים עשרה טיפין, ואמרי לה\u0004 \u0005[ויש אומרים\u0006 במקום שתים עשרה\u0005]:\u0006 \u0003שש עשרה טיפין, שכולן מראות לובן הן, אלא שזה למעלה מזה וזה למעלה מזה.\u0004","ודוחים: \u0003אימור דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' עקיבא\u0004 אומר שארבעת מראות הנגעים האמורים בדברי חכמים הם זה למעלה מזה, הרי זה \u0003ב\u0004נגע \u0003פתוך\u0004 (מעורב בצבע אדום, \"בהרת לבנה אדמדמת\", ויקרא יג, יט), שיש בו דרגות שונות של אדמימות, כמבואר להלן, אבל \u0003ב\u0004נגע \u0003חלוק\u0004 (עומד לעצמו, שאינו מעורב) \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שזה למעלה מזה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כי היכי דשמעת ליה\u0004 \u0005[כמו ששמעת אותו]\u0006 \u0003בפתוך, הכי שמעת ליה\u0004 \u0005[כך שמעת אותו]\u0006 \u0003בחלוק\u0004 שדין אחד להם, עדיין יש לשאול: \u0003ובפתוך גופיה\u0004 \u0005[עצמו]\u0006 \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו\u0006 שכך הוא סבור\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 משנה\u0005],\u0006 \u0003ר' עקיבא אומר: אדמדם\u0004 (פתוך) \u0003שבזה ושבזה,\u0004 בנגעים השונים, צבעו \u0003כיין המזוג\u0004 (מהול) \u0003במים,\u0004 \u0003אלא של בהרת עזה\u0004 \u0003כשלג ושל סיד דיהה הימנה;\u0004"],["\u0003ואם איתא\u0004 \u0005[יש,\u0006 כן הוא\u0005],\u0006 \u0003\"של צמר דיהה הימנה\"\u0004 (מן הבהרת) \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי נגע השאת שהוא כצמר, הוא הבא אחרי הבהרת, ורק אחריו בא הסיד!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אין הכי נמי\u0004 \u0005[כך גם כן\u0006 יש לומר\u0005],\u0006 \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: לא שאמר ר' עקיבא \"של סיד דיהה הימנה\", אלא \"של צמר דיהה הימנה\".\u0004","ושבים לדון במשנה שאמרה כי מראות הנגעים הם שנים שהם ארבעה: בהרת הכתובה בתורה — עזה כשלג, שניה לה — לבנה כסיד היכל. שאת הכתובה בתורה — כצמר לבן, שניה לה — כקרום ביצה. ושואלים: \u0003ומנלן\u0004 \u0005[ומניין לנו]\u0006 ש\u0003בהרת עזה היא? אמר אביי: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אם בהרת לבנה היא\"\u0004 (ויקרא יג, ד), \u0003היא לבנה ו\u0004בהשוואה לה \u0003אין אחרת לבנה\u0004 כמותה.","ומביאים בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"בהרת\"\u0004 האמורה בכתוב — \u0003עמוקה\u0004 נראית נמוכה מעור הגוף בו היא נמצאת, \u0003וכן הוא אומר \"ומראה עמק מן העור\"\u0004 (ויקרא יג, כה), \u0003כמראה\u0004 אור \u0003חמה\u0004 על הארץ, \u0003העמוקה\u0004 כלומר, שנראית נמוכה \u0003מן הצל\u0004 שלידה. \u0003\"שאת\"\u0004 — \u0003אין \"שאת\" אלא גבוה, וכן הוא אומר \"על כל ההרים הרמים ועל כל הגבעות הנשאות\"\u0004 (ישעיהו ב, יד), ואם כן \"שאת\" הוא נגע הנראה גבוה מן הבהרת. \u0003\"ספחת\"\u0004 — \u0003אין \"ספחת\" אלא טפילה,\u0004 דבר הטפל ונספח לדבר אחר, \u0003וכן הוא אומר \"ואמר ספחני נא\u0004 אל אחת הכהונות לאכול פת לחם\" (שמואל א ב, לו), ומכאן שיש מראה נגע שהוא טפל ונספח לשאת, והוא הלבן כקרום ביצה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003טפילה לשאת, טפילה לבהרת מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר ר' זירא: נאמרה \"לבנה\" בשאת\u0004 (ויקרא יג, י) \u0003ונאמרה \"לבנה\" בבהרת\u0004 (ויקרא יג, ד), \u0003מה לבנה האמורה בשאת יש לה טפילה\u0004 — \u0003אף לבנה האמורה בבהרת יש לה טפילה,\u0004 כסיד היכל.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה\u0006 החכם\u0005]\u0006 מקור אחר לדבר: \u0003הטיל הכתוב לספחת בין שאת לבהרת\u0004 (\"שאת או ספחת או בהרת\" ויקרא יג, ב), \u0003לומר לך: כשם ש\u0004יש \u0003טפילה לשאת כך\u0004 יש \u0003טפילה לבהרת.\u0004","ועוד שנינו באותה משנה לעיל: \u0003שאת כצמר לבן.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"צמר לבן\"? אמר רב ביבי אמר רב אסי: צמר נקי\u0004 של טלה \u0003בן יומו שמכבנין בו\u0004 (שעוטפים אותו כדי שיישאר צמרו נקי) \u0003ל\u0004צורך עשיית בגדי \u0003מילת\u0004 (צמר מובחר).","\u0003אמר ר' חנינא: משל\u0004 להבין את דבריהם של \u0003רבנן\u0004 \u0005[חכמים]\u0006 ששנו משנה זו, של בהרת ותולדתה, שאת ותולדתה, \u0003למה הדבר דומה? לתרי מלכי ולתרי איפרכי\u0004 \u0005[לשני מלכים ולשני מושלים],\u0006 \u0003מלכו של זה למעלה ממלכו של זה, ואיפרכו של זה למעלה מאיפרכו של זה.\u0004","ותמהים: \u0003האי\u0004 \u0005[\u0006משל \u0005זה],\u0006 משמעו \u0003זה למעלה מזה וזה למעלה מזה הוא,\u0004 אם מסדרים אותם כסדר זה (מלך, מלך, מושל, מושל) ואין כאן שתי קבוצות שונות!","\u0003אלא\u0004 הכוונה היא לשני מלכים, כל אחד והמושל שתחתיו: \u0003מלכו של זה למעלה מאיפרכיה דנפשיה\u0004 \u0005[מאיפרכו,\u0006 מושלו \u0005שלו עצמו],\u0006 \u0003ומלכו של זה למעלה מאיפרכיה דנפשיה\u0004 \u0005[מאיפרכו,\u0006 מושלו \u0005שלו עצמו],\u0006 וכך בנגעים, בהרת ותולדתה, שאת ותולדתה.","\u0003רב אדא בר אבא אמר: כגון מלכא ואלקפטא, רופילא וריש גלותא\u0004 \u0005[המלך והמשנה למלך, שר הצבא וראש הגולה].\u0006 ומקשים: \u0003האי\u0004 \u0005[\u0006גם משל \u0005זה],\u0006 \u0003זה למעלה מזה הוא! אלא כגון מלכא ורופילא\u0004 \u0005[המלך ושר הצבא]\u0006 שכפוף למלך ישירות, ואינו כפוף אל המשנה למלך, למרות שהמשנה למלך חשוב ממנו, \u0003ואלקפטא וריש גלותא\u0004 \u0005[והמשנה למלך וראש הגולה]\u0006 שכפוף למשנה למלך ואינו כפוף לשר הצבא.","\u0003רבא אמר:\u0004 גם לדרך זו המשל אינו מדוייק, שכן המשנה למלך אינו מלך העומד בפני עצמו. אלא מדובר בשני מלכים ממש, \u0003כגון שבור מלכא\u0004 \u0005[המלך]\u0006 מלך פרס, \u0003וקיסר\u0004 רומי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: הי מינייהו\u0004 \u0005[איזה מהם]\u0006 \u0003עדיף,\u0004 שבור המלך הפרסי או קיסר רומי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בחורשיא קא אכיל ליה\u0004 \u0005[בחורשות הוא אוכל לו],\u0006 כלומר אינך מצוי בעולם, \u0003פוק חזי טיבעא דמאן סגי בעלמא\u0004 \u0005[צא וראה מטבעו של מי\u0006 מהם \u0005מהלך,\u0006 נוהג \u0005בעולם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ותאכל כל ארעא ותדושנה ותדקנה\"\u0004 (דניאל ז, כג), ו\u0003אמר ר' יוחנן: זו\u0004 מלכות \u0003רומי חייבת\u0004 (הרשעה), \u0003שטיבעה\u0004 (שמטבעה) \u0003יצא בכל העולם כולו.\u0004","\u0003רבינא אמר:\u0004 משל דברי חכמים, למה הדבר דומה — \u0003כגון גלימא דעמר ושחקיה, סדינא דכיתנא ושחקיה\u0004 \u0005[בגד צמר ובלאו, סדין של פשתן ובלאו].\u0006","שנינו במשנה לענין ידיעות הטומאה: \u0003את שיש בה ידיעה בתחלה וכו'.\u0004 ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין הכתוב\u0004 בפרשת קרבן עולה ויורד, העוסק באדם שנטמא (ויקרא ה, ב— ג), \u0003מדבר אלא בטומאת מקדש וקדשיו?\u0004 שהרי בכתוב עצמו אין הדבר מפורש.","ומשיבים: \u0003ודין\u0004 (לימוד מסברה) \u0003הוא: הואיל והזהיר וענש\u0004 הכתוב במקום אחר \u0003על הטומאה, וחייב קרבן על הטומאה\u0004 בפרשה זו, \u0003מה כשהזהיר וענש על הטומאה\u0004 — \u0003לא הזהיר וענש אלא על טומאת מקדש וקדשיו, אף כשחייב קרבן על הטומאה\u0004 — \u0003לא חייב אלא על טומאת מקדש וקדשיו.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמדובר במי שמטמא \u0003תרומה, ש\u0004מצאנו ש\u0003הזהיר\u0004 הכתוב על כך, \u0003וענש\u0004 במיתה (ככתוב \"ומתו בו כי יחללהו\". ויקרא כב, ט)! ומשיבים: \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003עון\u0004 שעונשו \u0003מיתה\u0004 במזיד, ש\u0003חייב עליה קרבן\u0004 אם היה שוגג. שאין אדם מביא קרבן חטאת בשוגג אלא רק על עוון שחייב עליו כרת. ולכן יש לפרש פרשה זאת דוקא על טומאת מקדש וקדשיו, שחייבים עליה כרת.","ושואלים: ועדיין \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שאין מביאים חטאת על עוון מיתה, אמורים ב\u0003קרבן\u0004 חטאת \u0003קבוע, אבל\u0004"],["קרבן \u0003עולה ויורד ניתי\u0004 \u0005[יביא]\u0006 על עוון כזה, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 מביא קרבן כזה על \u0003שמיעת קול\u0004 שאדם נשבע לשקר (בשגגה) שאין הוא יודע עדות לחבירו (\"ושמע קול אלה והוא עד או ראה או ידע אם לא יגיד\" ויקרא ה, א), \u0003ו\u0004על \u0003ביטוי שפתים\u0004 שבועת שקר סתם (\"נפש כי תשבע לבטא בשפתיים להרע או להיטיב\", ויקרא ה, ד), האמורים באותה פרשה, למרות שאין בהם עונש כרת במזיד!","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \"או כי יגע בטומאת אדם לכל טומאתו אשר יטמא \u0003בה\"\u0004 (ויקרא ה, ג), שבאה המלה \u0003\"בה\" למעוטי\u0004 \u0005[למעט]\u0006 \u0003תרומה,\u0004 ללמדנו שרק בעבירה זו (טומאת מקדש וקדשיו) מתחייב בקרבן זה, ולא על אכילת תרומה בטומאה, שאינו צריך להביא על טומאתה בשוגג קרבן עולה ויורד.","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003\"בה\"\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 דווקא טומאת \u0003מקדש,\u0004 ולצד ההפוך, לומר \u0003דלא סגי ליה\u0004 \u0005[שאין די לו]\u0006 לחוטא \u0003בקרבן עולה ויורד\u0004 כדי לכפר עליה, מפני חומרתה, \u0003עד דמייתי\u0004 \u0005[ש\u0006הוא \u0005מביא]\u0006 \u0003קרבן\u0004 חטאת \u0003קבוע,\u0004 ואף העני חייב להביא כבשה ולא פחות מכך!","בענין זה \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רבא עליה\u0004 \u0005[על]\u0006 \u0003רבי\u0004 את הכינוי \u0003\"דולה מים מבורות עמוקים\",\u0004 משום שמצא הסבר לדבר מתוך עיון מעמיק בכתובים.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הפסוק \"או נפש אשר תגע בכל דבר טמא או בנבלת חיה טמאה או בנבלת בהמה טמאה\" (ויקרא ה, ב), \u0003רבי אומר: אקרא אני\u0004 בפסוק זה \u0003\"חיה\"\u0004 בלבד, \u0003\"בהמה\" למה נאמרה?\u0004 והרי בהמה היא בכלל חיה! אלא ביטוי יתר זה בא ללמדנו, \u0003נאמר כאן \"בהמה טמאה\" ונאמר להלן\u0004 במי שאוכל במזיד מבשר קדשים כשהוא טמא \u0003\"בהמה טמאה\",\u0004 (\"ונפש כי תגע בכל טמא... או בבהמה טמאה... ואכל מבשר זבח השלמים אשר לה' ונכרתה הנפש ההיא מעמיה\", ויקרא ז, כא), \u0003מה להלן\u0004 מפורש שהכתוב מדבר ב\u0003טומאת\u0004 בשר \u0003קודש\u0004 — \u0003אף כאן\u0004 הכוונה היא ל\u0003טומאת\u0004 בשר \u0003קודש,\u0004 למרות שאין הדבר מפורש בכתוב.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור לחיוב קרבן עולה ויורד שבפרשה ככזו ל\u0003טומאת קודש, טומאת מקדש\u0004 שאדם נכנס למקדש כשהוא טמא, \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שגם היא בכלל חיוב זה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין אשה הטמאה לאחר לידתה: \u0003\"בכל קדש לא תגע ואל המקדש לא תבא\"\u0004 (ויקרא יב, ד) ובפסוק זה \u0003איתקש\u0004 \u0005[הוקש]\u0006 \u0003מקדש לקודש\u0004 לדיני טומאה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שעל אותו פסוק האמור ביולדת אנו מסתמכים, \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 נחייב עליה קרבן עולה ויורד, שהרי \u0003אמר מר\u0004 \u0005[החכם]\u0006 במדרש ההלכה על אותו פסוק: \u0003\"בכל קדש לא תגע\"\u0004 — \u0003לרבות את התרומה!\u0004","ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה\u0006 כאן \u0005התורה]\u0006 תרומה מקרבן עולה ויורד, במלה \u0003\"בה\".\u0004 ומקשים: ו\u0003אימא\u0004 \u0005[ואמור]\u0006 ש\u0003\"בה\"\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 טומאת \u0003מקדש\u0004 ולא תרומה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי טומאת \u0003מקדש לא ממעטינן\u0004 \u0005[אין אנו ממעטים]\u0006 \u0003שכן\u0004 היא \u0003ב\u0004עונש \u0003כרת כמותה\u0004 כמו טומאת קודש, ואילו אכילת תרומה טמאה היא בעונש מיתה.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 טומאת \u0003תרומה לא ממעטינן\u0004 \u0005[אין אנו ממעטים],\u0006 שהיא דומה יותר לטומאת קודש, \u0003שכן\u0004 מתחייבים בה מיתה על ידי \u0003אכילה, כמותה,\u0004 ואילו טומאת מקדש חיובה היא בכניסה למקדש! ואם כן עדיין לא מצאנו מקור לחיוב קרבן עולה ויורד על טומאת מקדש.","\u0003אלא אמר רבא,\u0004 מכאן יש ללמוד: \u0003שלש כריתות\u0004 שנאמרו בתורה לענין טומאה \u0003ב\u0004קרבן \u0003שלמים, למה\u0004 נאמרו? \u0003אחת לכלל ואחת לפרט,\u0004 כלומר, במקום אחד נאמר הדבר בדרך כלל לגבי כל הקדשים (\"...כל איש אשר יקרב מכל זרעכם אל הקדשים אשר יקדישו בני ישראל לה' וטומאתו עליו ונכרתה הנפש ההיא מלפני...\", ויקרא כב, ג), ובמקום אחר נאמר הדבר בצורה מפורשת לגבי שלמים (\"והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה...\", ויקרא ז, כ), ולפי כללי מדרש ההלכה, שדבר שהיה בכלל ויצא מן הכלל ללמד, לא רק על עצמו לימד אלא על הכלל כולו, יש ללמוד שכרת זה חל לא רק על קרבן שלמים, אלא על כלל הקרבנות הנאכלים. \u0003ו\u0004כרת \u0003אחת\u0004 נוספת שנאמרה לגבי טומאת שלמים (\"ונפש כי תגע בכל טמא... ואכל מבשר זבח השלמים אשר לה' ונכרתה...\", ויקרא ז, כא) ואין בה צורך לעניינה, באה \u0003ל\u0004למדנו על \u0003טומאה הכתובה\u0004 במקום אחר \u0003בתורה\u0004 ב\u0003סתם,\u0004 בענין חיוב קרבן עולה ויורד, \u0003ואיני יודע מה היא\u0004 —","\u0003הוי אומר:\u0004 זו \u0003טומאת\u0004 בשר \u0003קודש,\u0004 כגון בשר שלמים. \u0003ואם אינו ענין לטומאת קודש, דנפקא ליה\u0004 \u0005[ש\u0006הרי \u0005יצאה לו\u0006 נלמדה\u0005]\u0006 כבר \u0003מ\u0004דבריו של \u0003רבי,\u0004 כמובא בברייתא לעיל, \u0003תנהו ענין לטומאת מקדש,\u0004 לומר שגם היא בכלל קרבן עולה ויורד.","ומקשים: \u0003והאי מיבעי ליה\u0004 \u0005[ו\u0006אולם כתוב נוסף \u0005זה נצרך לו]\u0006 \u0003לכ\u0004 דרשת \u0003ר' אבהו,\u0004 ש\u0003אמר ר' אבהו: שלש כריתות\u0004 שנאמרו \u0003בשלמים למה? אחת לכלל ואחת לפרט\u0004 כפי שאמר רבא לעיל, \u0003ואחת לדברים שאינן נאכלין,\u0004 כגון לבונה וקטורת, שאף על אכילתן בטומאה חייבים כרת.","\u0003ול\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר: דברים שאינן נאכלין אין חייבין עליהן כרת משום טומאה\u0004 — \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003חטאת הפנימית\u0004 (כגון פר ושעיר של יום הכיפורים, שדמם נזרק בפנים, בהיכל), לומר שאף על אכילתה בטומאה חייבים כרת, \u0003דסלקא דעתך אמינא\u0004 \u0005[ש\u0006כן \u0005יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר ר' שמעון: כל שאינו קרב על מזבח החיצון כשלמים אין חייבין עליו\u0004 כרת \u0003משום פיגול\u0004 (אם עשה אחת מעבודותיו על מנת לאוכלו או להקריבו לאחר זמנו) — \u0003משום טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יהיו חייבים עליו, \u0003קא משמע לן דמיחייב\u0004 \u0005[הריהו משמיע לנו ש\u0006הוא \u0005מתחייב]!\u0006 ואם כן, יש לדחות ראיה זו.","\u0003אלא אמרי נהרדעי משמיה\u0004 \u0005[אומרים\u0006 חכמי \u0005נהרדעא משמו]\u0006 של \u0003רבא:\u0004 אין מדובר בשלוש כריתות האמורות בשלמים, שהן נצרכות לכמו שדרש ר' אבהו. אלא כך יש לומר: \u0003שלש טומאות\u0004 האמורות \u0003בשלמים,\u0004 באותם פסוקים שנזכר בהם עונש הכרת, \u0003למה? אחת לכלל ואחת לפרט, ואחת לטומאה הכתובה בתורה סתם\u0004 בפרשת קרבן עולה ויורד \u0003ואיני יודע מה היא\u0004 —","\u0003הוי אומר טומאת קודש. ואם אינו ענין לטומאת קודש, דנפקא ליה\u0004 \u0005[ש\u0006הרי היא \u0005יוצאת לו,\u0006 נלמדת\u0005]\u0006 \u0003מ\u0004דברי \u0003רבי\u0004 — \u0003תנהו ענין לטומאת מקדש.\u0004","ומקשים: \u0003והאי נמי מיבעי ליה\u0004 \u0005[ו\u0006הרי \u0005זה גם כן נצרך לו],\u0006 \u0003איידי דבעי למכתב\u0004 \u0005[מתוך ש\u0006הוא \u0005צריך לכתוב]\u0006 \u0003כרת לכ\u0004 דרשת \u0003ר' אבהו\u0004 — \u0003כתב\u0004 בענין זה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003טמאות, דלא סגי לה בלאו הכי\u0004 \u0005[ש\u0006הרי \u0005אין די לה בלא כך],\u0006 להודיענו על מה הוא חייב כרת!","\u0003אלא אמר רבא:\u0004 ההלכה שקרבן עולה ויורד בא על טומאת מקדש \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"טומאתו\" \"טומאתו\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בפרשת קרבן עולה ויורד \u0003\"לכל טומאתו\"\u0004 (\"או כי יגע בטומאת אדם לכל טומאתו\", ויקרא ה, ג),"],["\u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בפרשת פרה אדומה: \"כל הנוגע במת... ולא יתחטא את משכן ה' טימא... \u0003טמא יהיה עוד טמאתו בו\"\u0004 (במדבר יט, יג), \u0003מה להלן\u0004 מדובר ב\u0003טומאת מקדש\u0004 (\"את משכן ה' טימא\"), \u0003אף כאן\u0004 מדובר ב\u0003טומאת מקדש.\u0004","ושואלים: \u0003ואלא\u0004 מאחר שהוכחנו שמדובר בפרשה זו על דברים שחייבים על טומאתם עונש כרת, אם כן המלה \u0003\"בה\"\u0004 (ויקרא ה, ג) שמיעטנו ממנה טומאה של תרומה, \u0003למה לי?\u0004 שכיון שאין חייבים עליה כרת, הרי מתחילה אינה נכנסת בכלל זה!","ומשיבים: מלה זו באה \u0003לרבות נבלת עוף טהור,\u0004 לומר שאף שטומאתה שונה, שאינה מטמאת במגעה אלא באכילתה — חייב קרבן עולה ויורד, אם נכנס למקדש לאחר שנטמא בה.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת:\u0004 כי \u0003\"בה\"\u0004 לשון \u0003מיעוטא\u0004 \u0005[\u0006\u0005מיעוט]\u0006 \u0003הוא,\u0004 ולא לשון ריבוי! ומשיבים: דווקא \u0003משום דמיעוטא\u0004 \u0005[שמיעוט]\u0006 \u0003הוא אייתר\u0004 \u0005[נעשה ייתור],\u0006 כיצד? \u0003כתיב\u0004 \u0005[נאמר]\u0006 תחילה בפסוק זה: \u0003\"או כי יגע\u0004 בטומאת אדם לכל טומאתו אשר יטמא בה\", ויש לדייק: מה שהוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003נגיעה,\u0004 שמטמא במגעו — \u0003אין\u0004 \u0005[כן],\u0006 חייבים על שגגגתו קרבן עולה ויורד, אבל מה \u0003דלאו\u0004 \u0005[שאינו]\u0006 \u0003בר נגיעה\u0004 — \u0003לא, וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר מכן \u0003\"בה\"\u0004 (\"לכל טומאתו אשר יטמא בה\"), והוא גם כן לשון \u0003מיעוטא\u0004 \u0005[מיעוט],\u0006 \u0003הוה\u0004 \u0005[הריהו]\u0006 \u0003מיעוט אחר מיעוט, ואין מיעוט\u0004 בא \u0003אחר מיעוט אלא לרבות,\u0004 ללמד שאף על נבלת עוף טהור, שאינה מטמאת במגע — חייבים קרבן עולה ויורד.","שנינו במשנה: טומאה ש\u0003יש בה ידיעה בתחלה ואין בה ידיעה בסוף\u0004 — \u0003שעיר הנעשה בפנים\u0004 ביום הכיפורים ויום הכפורים עצמו תולה, עד שייוודע לו שחטא ויביא כפרתו בקרבן עולה ויורד. ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על האמור בעבודת השעיר הנעשה בפנים: \u0003\"וכפר על הקדש מטמאת בני ישראל\u0004 ומפשעיהם לכל חטאתם\" (ויקרא טז, טז), ויש לברר מה הן טומאות אלה הנזכרות בכתוב, כי לכאורה","\u0003יש לי בענין זה להביא שלש טומאות: טומאת עבודה זרה, וטומאת גילוי עריות, וטומאת שפיכות דמים.\u0004","ומפרטים: \u0003בעבודה זרה הוא אומר:\u0004 \"מזרעו נתן למולך \u0003למען טמא את מקדשי\"\u0004 (ויקרא כ, ג), \u0003בגילוי עריות הוא אומר: \"ושמרתם את משמרתי לבלתי עשות מחקות התועבת\u0004 אשר נעשו לפניכם \u0003ולא תטמאו בהם\"\u0004 (ויקרא יח, ל), \u0003בשפיכות דמים הוא אומר:\u0004 \"...ולארץ לא יכופר לדם אשר שופך בה כי אם בדם שופכו, \u0003ולא תטמא את הארץ\"\u0004 (במדבר לה, לד). \u0003יכול על שלש טומאות הללו יהא שעיר מכפר? תלמוד לומר: \"מטמאת בני ישראל\"\u0004 כלומר, חלק מהן, \u0003ולא כל טומאות,\u0004","\u0003מה\u0004 איזו טומאה \u0003מצינו\u0004 (מצאנו) \u0003שחלק\u0004 (שהבדיל) אותה \u0003הכתוב\u0004 במקום אחר \u0003מכלל כל טומאות\u0004 — \u0003הוי אומר טומאת מקדש וקדשיו,\u0004 שמביאים עליה קרבן עולה ויורד, \u0003אף כאן\u0004 מדובר \u0003בטומאת מקדש וקדשיו, דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר:\u0004 אין צורך ללמוד ממקום אחר, אלא \u0003ממקומו\u0004 מפסוק זה עצמו \u0003הוא מוכרע,\u0004 ש\u0003הרי הוא אומר: \"וכפר על הקדש מטמאת\",\u0004 ומשמע: \u0003מטומאות של קודש.\u0004","וממשיכים לדון: \u0003יכול על כל טומאה שבקודש,\u0004 \u0003יהא שעיר זה מכפר? תלמוד לומר: \"ומפשעיהם לכל חטאתם\",\u0004 ומלשון זו עולה שמדובר ב\u0003חטאים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פשעים\u0004 (עבירות של זדון), \u0003מה פשעים שאינם בני קרבן,\u0004 שהרי אין מביאים קרבן חטאת על זדון, \u0003אף חטאים\u0004 שמדובר עליהם כאן, שהשעיר הפנימי מכפר עליהם, הם חטאים \u0003שאינם בני קרבן,\u0004 שאין בהם התנאים לחייב קרבן חטאת. והם אלו שמתחילה לא היתה בהם ידיעה על הטומאה, לפי שאין מביאים קרבן חטאת אלא על טומאה שיש בה ידיעה בתחילה וידיעה בסוף והעלם בינתיים.","וממשיכים לדון: \u0003ומנין ל\u0004טומאה ש\u0003יש בה ידיעה בתחלה ואין בה ידיעה בסוף, ששעיר זה תולה,\u0004 למרות שאינו בר קרבן? \u0003תלמוד לומר \"לכל חטאתם\"\u0004 — \u0003חייבי חטאות במשמע\u0004 כלומר, אלו שיכולים לבוא לידי קרבן חטאת. ומי שהיתה לו ידיעה בתחילה ונעלמה ממנו, הרי ייתכן שיחזור וייוודע לו — ואז יתחייב חטאת. ועל כך נאמר שעד שייוודע לו — השעיר הפנימי תולה ומכפר עליו. ומעתה באים לבאר דברי ברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יש לי בענין זה\u0004 של כפרת שעיר הפנימי ביום הכיפורים, \u0003להביא שלש טומאות: טומאת עבודה זרה, וטומאת גילוי עריות, וטומאת שפיכות דמים.\u0004","ושואלים: \u0003האי\u0004 \u0005[אותה]\u0006 טומאת \u0003עבודה זרה\u0004 שיש להביא בענין זה, \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003במזיד\u0004 עבר — הרי \u0003בר קטלא\u0004 \u0005[בן\u0006 עונש \u0005מיתה]\u0006 \u0003הוא,\u0004 ואין לו כפרה בקרבן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשוגג\u0004 — הלוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003קרבן\u0004 חטאת \u0003הוא,\u0004 ואין מתכפר לו עד שיביא את חטאתו!","ומשיבים: מדובר \u0003במזיד ו\u0004במקרה ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו],\u0006 ואז אין עונשים אותו במיתה, וכן \u0003בשוגג ו\u0004במקרה ש\u0003לא אתיידע ליה\u0004 \u0005[נודע לו]\u0006 על חטאו עד יום הכיפורים, והיה מקום לומר שיתכפר בשעיר הפנימי."],["ועוד שואלים: \u0003גילוי עריות נמי\u0004 \u0005[גם כן]\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003במזיד\u0004 עשה — \u0003בר קטלא\u0004 \u0005[בן\u0006 עונש \u0005מיתה]\u0006 \u0003הוא, אי\u0004 \u0005[אם]\u0006 \u0003בשוגג\u0004 — \u0003בר\u0004 \u0005[בן]\u0006 \u0003קרבן הוא!\u0004","ומשיבים: אפשר לומר שהיה הדבר בשני האופנים, או \u0003במזיד ולא אתרו ביה\u0004 \u0005[התרו בו]\u0006 קודם לעבירה, ולכן אינו חייב מיתה, או \u0003בשוגג ולא אתידע ליה\u0004 \u0005[נודע לו].\u0006","ועוד שואלים: \u0003שפיכות דמים נמי\u0004 \u0005[גם כן]\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003במזיד\u0004 — \u0003בר קטלא\u0004 \u0005[בן מיתה]\u0006 \u0003הוא, אי\u0004 \u0005[אם]\u0006 \u0003בשוגג\u0004 הרג — \u0003בר\u0004 \u0005[בן]\u0006 \u0003גלות הוא,\u0004 שהרי ההורג אדם בשוגג חייב לגלות לעיר מקלט!","ומשיבים: מדובר או \u0003במזיד ולא אתרו ביה\u0004 \u0005[התרו בו],\u0006 או \u0003בשוגג ולא אתידע ליה\u0004 \u0005[נודע לו].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003בהנך דלאו\u0004 \u0005[באותם שלא]\u0006 \u0003בני גלות נינהו\u0004 \u0005[הם],\u0006 שיש מקרים שההורג אדם בשוגג אינו חייב גלות, כגון שהיתה השגגה קרובה לאונס או לזדון.","וממשיכים לדון בדברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול על שלש טומאות הללו יהא שעיר\u0004 הפנימי \u0003מכפר? תלמוד לומר:\u0004 \"וכפר על הקודש \u0003מטמאות\u0004 בני ישראל ומפשעיהם לכל חטאתם\" (ויקרא טז, טז), \u0003ולא \"כל טומאות\", מה מצינו\u0004 (מצאנו) דבר \u0003שחלק\u0004 אותו \u0003הכתוב מכלל כל הטומאות?\u0004 הרי זה \u0003בטומאת מקדש וקדשיו, אף כאן\u0004 שמדובר בחלק מן הטומאות, הרי זה \u0003בטומאת מקדש וקדשיו,\u0004 אלו \u0003דברי ר' יהודה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[במה]\u0006 \u0003חלק\u0004 אותו מכל השאר, \u0003דמייתי\u0004 \u0005[שמביא\u0006 אותו\u0005]\u0006 \u0003בעולה ויורד?\u0004 שיש הבדל בקרבן אם הוא עני או עשיר, והרי הוא חלוק בכך משאר העבירות שהקרבן עליהם הוא אחד וקבוע? ואולם אם זו ההבחנה \u0003אימא\u0004 \u0005[אמור]\u0006 שמדובר כאן ב\u0003עבודה זרה, ומאי\u0004 \u0005[ומה]\u0006 \u0003חלק\u0004 בה?","\u0003(סימן: עבודה זרה יולדת מצורע נזיר (וכו'))\u0004 שעל עבירה זו \u0003מייתי\u0004 \u0005[מביא]\u0006 דווקא","\u0003שעירה\u0004 לחטאת \u0003ולא כשבה!\u0004","\u0003אמר רב כהנא: אנן\u0004 \u0005[אנחנו]\u0006 \u0003חלק להקל קאמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 בעבודה זרה \u0003חלק להחמיר הוא.\u0004","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 שמדובר בטומאת \u0003יולדת,\u0004 ש\u0003חלק\u0004 אותה הכתוב משאר טומאות, \u0003דמייתא\u0004 \u0005[שמביאה]\u0006 \u0003עולה ויורד,\u0004 שגם בה יש הבדל אם עשירה או עניה היא! \u0003אמר רב הושעיא:\u0004 נאמר שם \u0003\"לכל חטאתם\"\u0004 (ויקרא טז, טז), \u0003ולא \"לכל טומאתם\",\u0004 ואילו הקרבן של היולדת הוא כדי להיטהר מן הטומאה ולא מן החטא.","ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון בן יוחאי\u0004 ש\u0003אמר: יולדת נמי\u0004 \u0005[גם כן]\u0006 \u0003חוטאת היא,\u0004 והיא מביאה חטאת משום שבזמן צער הלידה היא נשבעת שבועה שאינה מקיימת, שלא תלד עוד, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003ר' שמעון לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר\u0004 בענייננו: \u0003ממקומו הוא מוכרע\u0004 ואינו נזקק לדרשה זו של \"חלק הכתוב\".","ושואלים עוד: \u0003אימא\u0004 \u0005[אמור]\u0006 שמדובר ב\u0003מצורע,\u0004 שיש הבדל בקרבנו אם עשיר או עני הוא! \u0003אמר רב הושעיא:\u0004 נאמר \u0003\"לכל חטאתם\" ולא \"לכל טומאתם\",\u0004 וקרבנו של המצורע אינו בא על חטא אלא על טומאה.","ושואלים: \u0003ול\u0004דעת \u0003ר' שמואל בר נחמני\u0004 ש\u0003אמר: על שבעה דברים\u0004 של עבירה \u0003נגעים באין,\u0004 משמע שלדעתו צרעת קשורה בחטא, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003התם נגעיה דאכפר ליה\u0004 \u0005[שם נגעו\u0006 הוא זה שגרם \u0005שנתכפר לו],\u0006 שהנגע כשלעצמו הוא הכפרה על החטא, \u0003וקרבן\u0004 שהוא מביא \u0003לאישתרויי\u0004 \u0005[להתיר אותו]\u0006 \u0003בקהל\u0004 הוא בא, שלא יהיה עוד בנידוי.","ושואלים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמדובר ב\u0003נזיר טמא,\u0004 ש\u0003חלק\u0004 אותו משאר טומאות, \u0003דמייתי\u0004 \u0005[שמביא]\u0006 הנזיר העני \u0003תורים ובני יונה! אמר רב הושעיא:\u0004 גם פה צריך לומר את דיוק הכתוב: \u0003\"לכל חטאתם\" ולא \"לכל טומאתם\",\u0004 והרי לא מפני החטא הנזיר מביא את קרבנו.","ושואלים: \u0003ול\u0004דעת \u0003ר' אלעזר הקפר\u0004 ש\u0003אמר: נזיר נמי\u0004 \u0005[גם כן]\u0006 \u0003חוטא הוא,\u0004 שההינזרות מן היין חטא היא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' שמעון,\u0004 ש\u0003אמר\u0004 בענייננו: \u0003ממקומו הוא מוכרע.\u0004","ובהמשך ביאורה של הברייתא שהבאנו, \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' שמעון אומר: ממקומו הוא מוכרע,\u0004 כיצד? \u0003הרי הוא אומר: \"וכפר על הקדש מטמאות\"\u0004 (ויקרא טז, טז), לומר שהוא מכפר \u0003מטומאתו של קודש,\u0004 והרי זו ראיה מגוף הכתוב שבענין זה מדובר. ושואלים: הלוא \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' שמעון\u0004 והדבר מוכרע באמת ממקומו, ולמה צריך לראיה אחרת? ומסבירים, \u0003ור' יהודה אמר לך\u0004 \u0005[יכול לומר לך]\u0006 בתשובה: \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \"וכיפר על הקודש\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לענין אחר, ללמדנו: \u0003כי היכי דעביד\u0004 \u0005[כמו ש\u0006הוא \u0005עושה]\u0006 \u0003לפני ולפנים,\u0004 שהוא מזה מדם הפר והשעיר בקדש הקדשים, \u0003הכי נעביד\u0004 \u0005[כך יעשה]\u0006 \u0003בהיכל,\u0004 שהמילים \"וכיפר על הקודש\" משמען שהוא עושה הזיה על ההיכל.","ומן הצד האחר, \u0003ור' שמעון,\u0004 מה הוא משיב על כך? לדעתו \u0003ההוא\u0004 \u0005[אותו\u0006 דין\u0005]\u0006 \u0003מ\"וכן יעשה\u0004 לאהל מועד\" \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006 \u0003ו\u0004לעומתו \u0003ר' יהודה,\u0004 מה הוא משיב על הסבר זה? \u0003אי מההיא\u0004 \u0005[אם ממנו],\u0006 אם היה כתוב רק \"וכן יעשה\", ולא היה כתוב \"וכיפר על הקודש\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ש\"וכן יעשה\" משמעו: \u0003ניתי\u0004 \u0005[שיביא]\u0006 \u0003פר ושעיר אחריני\u0004 \u0005[אחרים]\u0006 \u0003ונעביד\u0004 \u0005[ויעשה]\u0006 אותם בהיכל, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \"וכיפר על הקודש\" שנאמר תחילה, שמאותו דם שכיפר בו בקדש הקדשים מכפר על ההיכל. ושואלים: \u0003ור' שמעון,\u0004 מה הוא אומר על כך? לדעתו לא היה מקום לטעות בכך, שכן \u0003\"וכן יעשה לאהל מועד\"\u0004 — \u0003מיניה\u0004 \u0005[ממנו]\u0006 \u0003משמע,\u0004 שמאותו קרבן הוא עושה גם באוהל מועד.","ועוד בפירוש הברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול על כל טומאות שבקודש יהא שעיר זה מכפר? תלמוד לומר: \"מפשעיהם לכל חטאתם\",\u0004 חטאים בדומה לפשעים, שאינם בני קרבן. ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הם]\u0006 אותן טומאות שבקודש, שסבור היית ששעיר הפנימי מכפר עליהן — טומאה ש\u0003יש בה ידיעה בתחלה ויש בה ידיעה בסוף.\u0004 אולם מדוע יכפר עליו השעיר? והרי \u0003האי\u0004 \u0005[זה]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003קרבן הוא,\u0004 שהרי עליו אמרה תורה שצריך להביא קרבן עולה ויורד על שגגתו, ואין יום הכיפורים פוטר אדם מלהקריב חטאתו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאתידע ליה\u0004 \u0005[שנודע לו]\u0006 חטאו רק \u0003סמוך לשקיעת החמה\u0004 לפני יום הכיפורים, ולא הספיק להביא קרבן. ובמקרה זה \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה בדעתך לומר]:\u0006 \u0003אדמייתי\u0004 \u0005[עד ש\u0006הוא \u0005מביא]\u0006 את הקרבן בפועל"],["\u0003ניתלי ליה\u0004 \u0005[שיתלה לו]\u0006 ויצילנו מן העונש ומן היסורים בינתיים, עד שיביא את קרבנו, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר כן.","וממשיכים לדון בברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מנין\u0004 לעבירה \u0003שיש בה ידיעה בתחלה ואין בה ידיעה בסוף ששעיר זה\u0004 הפנימי \u0003תולה?\u0004 ותוהים על עצם השאלה: \u0003מנין?!\u0004 הלוא כבר הוכחנו דבר זה, \u0003מאי קא קשיא ליה\u0004 \u0005[מה היה קשה לו]\u0006 בראיה זו, שנדרש הוא לראיה אחרת?","ומשיבים: \u0003הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו],\u0006 \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 שמקור הדין הוא בכתוב \"מפשעיהם לכל חטאתם\" (ויקרא טז, טז) ואתה למד ש\u0003חטאים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פשעים, מה פשעים דלאו\u0004 \u0005[שאין\u0006 הם\u0005]\u0006 \u0003בני קרבן אף חטאים נמי\u0004 \u0005[גם כן]\u0006 \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן, אימא\u0004 \u0005[אמור]\u0006 באופן אחר: \u0003מה פשעים\u0004 הכוונה \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן לעולם, אף חטאים\u0004 אלה \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן לעולם, ומאי נינהו\u0004 \u0005[ומהם\u0006 חטאים \u0005אלה]\u0006 שאין מביאים עליהם קרבן כלל? זו טומאה ש\u0003אין בה ידיעה בתחלה ויש בה ידיעה בסוף,\u0004 שכיון שאין בה ידיעה מתחילה אינו חייב בקרבן עולה ויורד. \u0003אבל\u0004 עבירה ש\u0003יש בה ידיעה בתחלה ואין בה ידיעה בסוף, כיון דכי מתידע ליה\u0004 \u0005[שכאשר יתוודע לו\u0006 הדבר לבסוף\u0005]\u0006 \u0003בר\u0004 \u0005[בן\u0006 חיוב\u0005]\u0006 \u0003קרבן הוא\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ליתלי\u0004 \u0005[יתלה]\u0006 לו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 טומאה ש\u0003אין בה ידיעה בתחלה ויש בה ידיעה בסוף\u0004 — דבר זה \u0003שעיר הנעשה בחוץ ויום הכפורים מכפר,\u0004","\u0003סלקא דעתך אמינא ניפוך מיפך\u0004 \u0005[יעלה על דעתך לומר שנהפוך\u0006 את הדברים\u0005],\u0006 ונאמר ששעיר הנעשה בפנים הוא יכפר על שאין בו ידיעה בתחילה, והחיצון יתלה את כפרתה של טומאה שיש בה ידיעה בתחילה, שהרי בכתוב לא נתפרש על מה מכפר כל אחד מן השעירים. על כן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין שעיר הפנימי: \"וכיפר... \u0003לכל חטאתם\"\u0004 (ויקרא טז, טז), \u0003מכלל\u0004 הדברים אתה למד שמדובר באלה ש\u0003בני\u0004 \u0003חטאות נינהו\u0004 \u0005[הם],\u0006 והרי רק כאשר היתה ידיעה בתחילה, יוכל להביא קרבן כאשר יוודע לו לבסוף.","ושואלים: \u0003ונתכפר\u0004 \u0005[ושיתכפר]\u0006 על ידי שעיר זה \u0003כפרה גמורה,\u0004 ולא יצטרך לכפרה אחרת גם כשייוודע לו! ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \"וכיפר... \u0003מחטאתם\"\u0004 הייתי באמת מפרש \u0003כדקא אמרת\u0004 \u0005[כמו שאתה אומר],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"לכל חטאתם\"\u0004 כוונתו \u0003להנך דאתו\u0004 \u0005[לאותם שבאים]\u0006 בסופו של דבר \u0003לכלל חטאת,\u0004 כשייוודע להם.","ושואלים: \u0003וכי מאחר ש\u0004השעיר הפנימי \u0003אינו מכפר,\u0004 אם כן \u0003למה תולה? אמר ר' זירא: לומר, שאם מת\u0004 לפני שהביא כפרתו — \u0003מת בלא עון. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם מת\u0004 אינו צריך לכך, כי ה\u0003מיתה\u0004 עצמה \u0003ממרקת\u0004 ומנקה אותו מכל עוונותיו! \u0003אלא אמר רבא:\u0004 תליה זו היא \u0003להגן עליו מן היסורין,\u0004 שלא ייענש עד שיביא את קרבנו.","שנינו במשנה: \u0003אין בה ידיעה בתחלה ויש בה ידיעה בסוף\u0004 — \u0003שעיר הנעשה בחוץ ויום הכפורים מכפר,\u0004 שנאמר \"מלבד חטאת הכפורים...\" (במדבר כט, יא), מה הפנימי אין מכפר אלא על דבר שיש בו ידיעה, אף החיצון אין מכפר אלא על דבר שיש בו ידיעה.","ושואלים: \u0003מכדי איתקושי איתקוש להדדי\u0004 \u0005[הואיל והוקשו,\u0006 הושוו השעירים \u0005זה לזה],\u0006 \u0003ונכפר\u0004 \u0005[ושיכפר]\u0006 השעיר ה\u0003פנימי אדידיה\u0004 \u0005[על שלו],\u0006 על הדברים שהוא מכפר, \u0003ו\u0004על הדברים שמכפר השעיר ה\u0003חיצון, ונפקא מינה\u0004 \u0005[ויוצאת מכאן]\u0006 מסקנה למעשה \u0003להיכא\u0004 \u0005[למקום]\u0006 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 את השעיר ה\u0003חיצון,\u0004 שיתכפרו ישראל בשעיר הפנימי! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וכפר אהרן על קרנותיו \u0003אחת\u0004 בשנה\" (שמות ל, י), לומר: \u0003כפרה אחת מכפר\u0004 השעיר הפנימי, \u0003ואינו מכפר שתי כפרות.\u0004","ושואלים באופן אחר: כיון שיש היקש, \u0003ונכפר\u0004 \u0005[ושיכפר]\u0006 \u0003חיצון אדידיה\u0004 \u0005[על שלו]\u0006 על זה שהוא בעצמו מכפר, \u0003ואמאי דעביד\u0004 \u0005[ועל מה שעושה,\u0006 תולה\u0005]\u0006 הקרבן ה\u0003פנימי, נפקא מינה\u0004 \u0005[יוצאת מכאן]\u0006 תוצאה למעשה, \u0003ל\u0004ענין \u0003טומאה\u0004 ש\u0003אירעה בין זה לזה\u0004 שיתכפר בשעיר החיצון! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שוב באותו פסוק: \"מדם חטאת הכפורים \u0003אחת בשנה\u0004 יכפר עליו\", לומר: \u0003כפרה זו\u0004 שמכפר השעיר הפנימי \u0003לא תהא\u0004"],["\u0003אלא אחת בשנה.\u0004","ועל מה ששנינו במשנה כי שעיר החיצון מכפר על טומאה שלא היתה לו בה ידיעה בתחילה והיתה לו ידיעה בסוף, שאינו מביא עליה קרבן עולה ויורד, שואלים: \u0003ול\u0004דעת \u0003ר' ישמעאל\u0004 ש\u0003אמר:\u0004 טומאה ש\u0003אין בה ידיעה בתחלה ויש בה ידיעה בסוף בר\u0004 \u0005[בן\u0006 חיוב\u0005]\u0006 \u0003קרבן הוא,\u0004 שגם על כך מביא קרבן עולה ויורד. אם כן \u0003שעיר הנעשה בחוץ אמאי\u0004 \u0005[על מה]\u0006 הוא \u0003מכפר?\u0004 ומשיבים: \u0003על\u0004 אותה טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף.\u0004","ומקשים: אולם על \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003שעירי הרגלים ושעירי ראשי חדשים מכפרין!\u0004 ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 בענין זה \u0003כר' מאיר,\u0004 ש\u0003אמר: כל השעירים\u0004 של חטאות המוספים, ובכלל זה השעיר החיצון של יום הכיפורים, \u0003כפרתן שוה,\u0004 שהם מכפרים \u0003על טומאת מקדש וקדשיו.\u0004","ושואלים: \u0003אלא\u0004 לפי שיטה זו, שהשעיר החיצון אינו מכפר על דבר שיש בו ידיעה, כשעיר הפנימי, \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה,\u0006 לאיזה ענין\u0005]\u0006 \u0003איתקש\u0004 \u0005[הוקש]\u0006 השעיר ה\u0003חיצון לפנימי?\u0004 ומשיבים: ללמדנו, \u0003מה פנימי אינו מכפר בשאר עבירות,\u0004 אלא רק על טומאת מקדש וקדשיו, \u0003אף חיצון אינו מכפר בשאר עבירות.\u0004","שנינו במשנה: \u0003על שאין בה ידיעה בתחלה ולא בסוף\u0004 — \u0003שעירי רגלים ושעירי ראשי חדשים מכפרין,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר רב יהודה אמר שמואל: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושעיר עזים אחד לחטאת לה' \"\u0004(במדבר כח, טו), לומר: על \u0003חטא\u0004 כזה \u0003שאין מכיר בו אלא ה',\u0004 שאין בו ידיעה כלל, לא בתחילה ולא בסוף — \u0003יהא שעיר זה מכפר.\u0004","ושואלים: \u0003והאי מיבעי ליה\u0004 \u0005[והרי\u0006 כתוב זה \u0005נצרך לו]\u0006 \u0003ל\u0004לימוד אחר, \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש: מה נשתנה שעיר\u0004 זה \u0003של ראש חדש שנאמר\u0004 רק \u0003בו \"לה' \"? אמר הקדוש ברוך הוא\u0004 כביכול: \u0003שעיר זה יהא\u0004 ל\u0003כפרה\u0004 עלי (\"לה' \") \u0003על שמיעטתי את הירח!\u0004","ומשיבים: \u0003אם כן,\u0004 אם רק כדי לומר דבר זה, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \"חטאת \u0003על ה' \",\u0004 \u0003מאי\u0004 \u0005[מה]\u0006 טעם כתב \u0003\"לה' \"\u0004— \u0003לכדאמרן\u0004 \u0005[לכמו שאמרנו],\u0006 שהוא מכפר על דברים הידועים רק לה'.","ושואלים: \u0003ואימא כוליה\u0004 \u0005[ואמור\u0006 ש\u0005כל\u0006 המקרא הזה\u0005]\u0006 רק \u0003להכי\u0004 \u0005[לכך\u0006 לענין זה\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ולא כדברי ריש לקיש כלל! ומשיבים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"חטאת ה' \", מאי\u0004 \u0005[מה]\u0006 טעם אמר \u0003\"לה' \"? שמעת מינה תרתי\u0004 \u0005[לומד אתה מזה שני\u0006 דברים\u0005].\u0006","ושואלים: \u0003ונכפר נמי\u0004 \u0005[ושיכפר\u0006 שעיר זה \u0005גם כן]\u0006 לא רק על טומאת מקדש וקדשיו, אלא \u0003אפילו בשאר עבירות\u0004 על כל עבירה שנעשתה בשגגה ולא נודעת כלל לעושה אותה! ומשיבים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל וזה\u0004 שעיר של ראש חדש \u0003בא בזמן קבוע, וזה\u0004 שעיר של יום הכיפורים \u0003בא בזמן קבוע,\u0004 יש ללמוד: \u0003מה זה\u0004 של יום הכיפורים \u0003אינו מכפר אלא על טומאת מקדש וקדשיו, אף זה\u0004 של ראש חודש \u0003אינו מכפר אלא על טומאת מקדש וקדשיו.\u0004","ואומרים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לסברה זו לגבי \u0003שעירי ראשי חדשים, שעירי הרגלים מנלן\u0004 \u0005[מנין לנו]\u0006 שהם מכפרים על טומאת מקדש וקדשיו? \u0003וכי תימא: הא נמי\u0004 \u0005[ואם תאמר: זה גם כן]\u0006 \u0003כדתנא דבי\u0004 \u0005[כ\u0006דברי \u0005התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 הואיל והם באים בזמן קבוע — \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך\u0006 את ההשוואה\u0005]\u0006 ולומר: \u0003אי\u0004 \u0005[אם]\u0006 אתה רוצה ללמוד \u0003מ\u0004שעיר של \u0003ראש חדש,\u0004 יש לדחות: \u0003שכן תדיר\u0004 יותר מאשר הרגלים! \u0003אי\u0004 \u0005[אם]\u0006 אתה רוצה ללמוד \u0003מ\u0004של \u0003יום הכפורים\u0004 — אף הוא שונה, \u0003שכן מרובה כפרתו\u0004 של יום הכיפורים, שמכפר על כל העוונות! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006"],["\u0003הא גמרינן\u0004 \u0005[הרי למדים אנו]\u0006 שעיר של \u0003ראש חדש מ\u0004שעיר של \u0003יום הכפורים ולא פרכינן\u0004 \u0005[ואין אנו מקשים]!\u0006 על כך יש להשיב: \u0003התם\u0004 \u0005[שם]\u0006 בשעיר ראש חודש, \u0003כפרה\u0004 עצמה \u0003מיכתב כתיבא\u0004 \u0005[כתובה\u0006 היא\u0005],\u0006 ששעיר זה מכפר על חטא שאין בו ידיעה כלל, כפי שלמדנו מ\"לחטאת לה' \", והלימוד משעיר יום הכיפורים \u0003גלויי מילתא בעלמא\u0004 \u0005[גילוי דבר בלבד]\u0006 \u0003הוא, אבל הכא\u0004 \u0005[כאן],\u0006 בשעירי הרגלים, שאין אנו יודעים מן הכתוב שהם באים לכפר על חטא שאין בו ידיעה כלל, ואנו רוצים ללמוד משעיר יום הכיפורים, \u0003איכא למימר כולה מילתא לא גמרינן\u0004 \u0005[אפשר לומר\u0006 שאת \u0005כל הדבר אין אנו למדים]\u0006 שהרי, כאמור, מרובה כפרתו של שעיר יום הכיפורים!","\u0003אלא\u0004 מנין למדים דינם של שעירי הרגלים — \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003ר' חמא בר' חנינא\u0004 בהסבר שיטתו של ר' מאיר במשנה, שהיה יכול לכתוב במוספי הרגלים רק \u0003\"שעיר\",\u0004 וכתוב בהם \u0003\"ושעיר\",\u0004 ובא ו' החיבור להקיש את כולם יחד, לומר שדינם שווה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשיטת ר' יהודה, נלמד מן השינוי, שלא כתב \u0003\"שעיר\"\u0004 אלא \u0003\"ושעיר\", ואיתקיש\u0004 \u0005[והוקשו]\u0006 על ידי כך \u0003שעירי רגלים לשעירי ראשי חדשים,\u0004 שנזכרו תחילה באותה פרשה: \u0003מה שעירי ראשי חדשים אינן מכפרין אלא על\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף, אף שעירי הרגלים אינן מכפרין אלא על\u0004 טומאה \u0003שאין בה ידיעה לא בתחלה ולא בסוף.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהודה\u0004 ששעירי ראשי חודשים ושל רגלים מכפרים \u0003על שאין בה ידיעה לא בתחלה ולא בסוף,\u0004 האם \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003בחטא שאין סופו ליודע,\u0004 שהשגגה שבו היתה כזו שאינה יכולה להיוודע כלל, \u0003אבל חטא שסופו ליודע\u0004 — \u0003כמי שיש ידיעה בסוף דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004דבר זה \u0003שעיר הנעשה בחוץ ויום הכפורים מכפר\u0004 עליו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו חטא שסופו ליודע\u0004 — \u0003השתא מיהא\u0004 \u0005[עכשיו על כל פנים]\u0006 \u0003חטא שאין מכיר בו אלא ה' קרינא ביה\u0004 \u0005[קוראים אנו בו]?\u0006","כדי לפתור בעיה זו מציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003על שאין בה ידיעה לא בתחלה ולא בסוף וחטא שסופו ליודע\u0004 — \u0003שעירי הרגלים ושעירי ראשי חדשים מכפרים,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ונפתרה איפוא השאלה, שהרי בפירוש אמר ר' יהודה שגם חטא שסופו להיוודע מתכפר בזה, כיון שעכשיו אינו ידוע.","שנינו במשנה, \u0003ר' שמעון אומר: שעירי הרגלים מכפרין\u0004 על טומאה שאין בה ידיעה תחילה וסוף, \u0003אבל לא שעירי ראשי חדשים,\u0004 ועל מה שעירי ראשי חודשים מכפרים — על הטהור שאכל בשר קדשים טמא.","\u0003אמר ר' אלעזר אמר ר' אושעיא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואתה נתן לכם לשאת את עון העדה\"\u0004 (ויקרא י, יז), \u0003והאי קרא\u0004 \u0005[ופסוק זה]\u0006 \u0003בשעיר\u0004 של \u0003ראש חדש כתיב\u0004 \u0005[נאמר],\u0006 \u0003ויליף\u0004 \u0005[ולמד]\u0006 בגזירה שווה \u0003\"עון\" \"עון\" מציץ: נאמר כאן \"עון\", ונאמר להלן\u0004 בענין הציץ \u0003\"עון\"\u0004 (\"והיה על מצח אהרן ונשא אהרן את עון הקדשים\". שמות כח, לח), \u0003מה להלן\u0004 בציץ, מדובר בכפרה על \u0003טומאת בשר\u0004 (\"הקדשים\"), \u0003אף כאן\u0004 בשעיר ראש חודש, הוא כפרה על \u0003טומאת בשר.\u0004","ושואלים: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה להלן\u0004 מדובר רק ב\u0003עולין,\u0004 שהציץ רק מרצה על קרבנות שהועלו על המזבח בטומאה, שיעלו לרצון ולא יצטרכו להקריבם שנית, \u0003אף כאן\u0004 ב\u0003עולין\u0004, ולא בנאכלים כשהם טמאים! ומשיבים: בשעיר ראש חודש \u0003\"עון העדה\" כתיב\u0004 \u0005[נאמר],\u0006 משמע שהכפרה היא לאנשים האוכלים מן הקודש הטמא, ולא בריצוי הקרבנות.","ושואלים: \u0003מכדי מיגמר גמרי מהדדי\u0004 \u0005[הואיל\u0006 ו\u0005הם למדים זה מזה]\u0006 בגזירה שווה, נאמר כי \u0003נכפר\u0004 \u0005[יכפר]\u0006 שעיר של \u0003ראש חדש אדידיה ואדציץ\u0004 \u0005[על שלו,\u0006 על מה שהוא מכפר, \u0005ועל\u0006 מה ש\u0005הציץ\u0006 מכפר\u0005].\u0006 \u0003נפקא מינה\u0004 \u0005[יוצא מכאן\u0006 הבדל\u0005]\u0006 \u0003להיכא\u0004 \u0005[להיכן,\u0006 למקרה\u0005]\u0006 ש\u0003נשבר הציץ,\u0004 שבמקומו יכפר שעיר ראש חודש! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשעיר ראש חודש: \"לשאת את \u0003עון\u0004 העדה\", לומר: \u0003עון אחד\u0004 בלבד \u0003הוא נושא, ואין נושא שני עונות.\u0004","ושואלים מצד שני: \u0003ונכפר\u0004 \u0005[ויכפר]\u0006 \u0003ציץ אדידיה\u0004 \u0005[על שלו,\u0006 על הדברים שהוא מכפר\u0005]\u0006 \u0003ו\u0004על מה ששעיר \u0003ראש חדש\u0004 מכפר. \u0003נפקא מינה\u0004 \u0005[יוצא מכאן\u0006 הבדל\u0005]\u0006 \u0003ל\u0004ענין \u0003טומאה\u0004 ש\u0003אירעה בין זה לזה\u0004 כלומר, בין הבאת שעיר של ראש חודש אחד לשעיר של ראש חודש הבא! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אתה\u0004 נתן לכם לשאת את עון העדה\", לומר: \u0003אותה נושא עון,\u0004 דווקא חטאת זו מכפרת על עוון זה, \u0003ואין אחרת נושא עון\u0004 זה.","\u0003רב אשי אמר\u0004 ראיה נוספת: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בשעיר ראש חודש \u0003\"עון העדה\"\u0004 להדגיש: דווקא עוונה של \u0003עדה, ולא\u0004 עוון \u0003קדשים, והתם כתיב\u0004 \u0005[ושם,\u0006 בענין הציץ, \u0005נאמר]\u0006 \u0003\"עון הקדשים\"\u0004 — לומר לרצות על עוון ה\u0003קדשים ולא\u0004 עוון \u0003עדה,\u0004 ולכן כל אחד מהם מכפר על דבר לעצמו.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 איפוא\u0005]\u0006 לענין \u0003שעירי ראשי חדשים דמכפרי\u0004 \u0005[שמכפרים]\u0006 \u0003על טהור שאכל את הטמא, שעירי רגלים דמכפרי\u0004 \u0005[שמכפרים]\u0006 \u0003על\u0004 עבירה \u0003שאין בה ידיעה לא בתחלה ולא בסוף מנלן\u0004 \u0005[מנין לנו]\u0006 לפי שיטת ר' שמעון?","ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003ר' חמא בר' חנינא\u0004 להלן בשיטת ר' מאיר: \u0003\"שעיר\" \"ושעיר\",\u0004 שלמדים מו' החיבור שבשעירי המוספים (במדבר כח—כט) להקישם זה לזה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר \u0003\"שעיר\" \"ושעיר\",\u0004"],["\u0003ואיתקוש\u0004 \u0005[והוקשו]\u0006 \u0003שעירי הרגלים לשעירי ראשי חדשים,\u0004 ובאופן זה: \u0003מה שעיר\u0004 של \u0003ראש חודש במילתא\u0004 \u0005[בדבר]\u0006 של \u0003קודש מכפרי\u0004 \u0005[מכפרים],\u0006 \u0003אף שעירי רגלים במילתא\u0004 \u0005[בדבר]\u0006 של \u0003קודש\u0004 באנשים טמאים האוכלים קודש \u0003מכפרי\u0004 \u0005[מכפרים].\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003ניכפרו\u0004 \u0005[שיכפרו]\u0006 על מה שמכפר שעיר של \u0003ראש חדש\u0004 עצמו, בטהור שאכל טמא — \u0003הא אמרינן\u0004 \u0005[הרי\u0006 כבר \u0005אמרנו]\u0006 שיש לדייק מן המלה \u0003\"אתה\"\u0004 האמורה בשעיר ראש חודש, לומר: \u0003אותה נושא עון, ואין אחר נושא עון\u0004 זה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003ניכפרו\u0004 \u0005[שיכפרו]\u0006 על מה שמכפר שעיר של \u0003יום הכפורים\u0004 — \u0003הא אמרינן\u0004 \u0005[הרי אנו אומרים]:\u0006 נאמר בשעיר של יום הכיפורים \u0003\"אחת בשנה\"\u0004 (שמות ל, י), לומר \u0003כפרה זו\u0004 של יום הכיפורים \u0003לא תהא אלא אחת בשנה.\u0004","ואם כן, \u0003אמאי מכפרי\u0004 \u0005[על מה\u0006 הם \u0005מכפרים]?\u0006","\u0003אי\u0004 \u0005[אם]\u0006 \u0003על שיש בה ידיעה בתחלה ויש בה ידיעה בסוף,\u0004 הלוא \u0003האי\u0004 \u0005[זה]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003קרבן הוא,\u0004 שצריך להביא קרבן עולה ויורד על מה שחטא בשגגתו! \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003על שיש בה ידיעה בתחלה ואין בה ידיעה בסוף\u0004 — \u0003האי\u0004 \u0005[זה]\u0006 \u0003שעיר הנעשה בפנים ויום הכפורים תולה! אי\u0004 \u0005[אם]\u0006 \u0003על שאין בה ידיעה בתחלה אבל יש בה ידיעה בסוף\u0004 — \u0003האי\u0004 \u0005[זה]\u0006 \u0003שעיר הנעשה בחוץ ויום הכפורים מכפר!\u0004","\u0003על כרחך אינו מכפר אלא על שאין בה ידיעה לא בתחלה ולא בסוף.\u0004","שנינו במשנה, \u0003ר' מאיר אומר: כל השעירים\u0004 (של ראש חודש, של מועדים ושל יום הכיפורים) \u0003כפרתן שוה\u0004 על טומאת מקדש וקדשיו.","\u0003אמר ר' חמא בר ר' חנינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר? אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת קרבנות המועדים: \u0003\"שעיר\u0004 חטאת\" בתוספת ו' \u0003\"שעיר\",\u0004 ללמד ש\u0003הוקשו\u0004 (הושוו) \u0003כל השעירים זה לזה,\u0004 ש\u0003וי\"ו\u0004 שיש בכל \"ושעיר\" \u0003מוסיף על ענין ראשון,\u0004 ללמד שדינו כמו השעיר הנזכר קודם לכן באותה פרשה. על דרך לימוד זו מתקשים, ומקדימים לכך הקדמה קצרה.","\u0003קסלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 כי בדרך לימוד זו \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 משעירי המועדים \u0003מחבריה גמר\u0004 \u0005[מחבירו\u0006 הוא \u0005למד],\u0006 שלמדים שעיר של פסח משל ראש חודש, ושל שבועות משל פסח וכו'. ולפי זה קשה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 ב\u0003כל התורה כולה למידין למד מלמד\u0004 כלומר, למדים בהיקש מדבר שנלמד גם הוא מהיקש, \u0003חוץ מקדשים שאין למידין למד מלמד!\u0004","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שכן במקרה זה \u0003כולהו מקמא גמרי\u0004 \u0005[כולם\u0006 כל השעירים \u0005מן הראשון למדים],\u0006 שהאות ו' הנוספת מקשרת שעיר של כל מועד עם השעיר הראשון, של ראש חודש.","ומקשים: \u0003תינח\u0004 \u0005[תניח]\u0006 שכך הוא ב\u0003כל\u0004 מועד \u0003דכתב ביה\u0004 \u0005[שכתוב בו]\u0006 \u0003\"ושעיר\",\u0004 אולם \u0003עצרת ויום הכפורים דלא כתב ביה\u0004 \u0005[שלא כתוב בו]\u0006 \u0003\"ושעיר\",\u0004 \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006","\u0003אלא\u0004 יש להסביר את טעמו של ר' מאיר באופן אחר, \u0003אמר ר' יונה, אמר קרא\u0004 \u0005[הכתוב]\u0006 בסוף פרשת מוספי המועדים: \u0003\"אלה תעשו לה' במועדיכם\"\u0004 (במדבר כט, לט), \u0003הוקשו\u0004 על ידי כך \u0003כל המועדים כולן זה לזה,\u0004 ומכאן למדים ששעירי החטאת הנזכרים בהם מכפרים על אותו עוון. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ראש חדש לאו\u0004 \u0005[לא]\u0006 \u0003מועד הוא!\u0004","ודוחים: \u0003איברא\u0004 \u0005[באמת],\u0006 \u0003ראש חדש נמי איקרי\u0004 \u0005[גם כן נקרא]\u0006 \u0003מועד, כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003אביי\u0004 לענין אחר, ש\u0003אמר אביי:\u0004 חודש \u0003תמוז דההיא שתא\u0004 \u0005[של אותה שנה]\u0006 שחטאו בה בני ישראל במדבר בחטא המרגלים, \u0003מלויי מליוהו\u0004 \u0005[מילאו אותו],\u0006 שהיה תמוז אז בן שלושים יום, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קרא עלי מועד לשבר בחורי\"\u0004 (איכה א, טו). כלומר, נקבע מועד (יום נוסף של ראש חודש) שבגללו נגזרה גזירה שיהא החורבן בעתיד בתשעה באב, כפי שאמרו חכמים (תענית כט,א). ולענייננו למדנו שראש חודש נקרא מועד.","ועל דברי ר' מאיר שכל השעירים כפרתם שווה, \u0003אמר ר' יוחנן: ומודה ר' מאיר בשעיר\u0004 יום הכיפורים \u0003הנעשה בפנים\u0004 בקדש הקדשים, \u0003שהוא אינו מכפר כפרתן\u0004 של שאר שעירי החטאת, \u0003והן אינן מכפרין כפרתו.\u0004","ומסבירים: \u0003הוא אינו מכפר כפרתן,\u0004 כפי שלמדנו מן \"אחת\" האמור בו, ש\u0003כפרה אחת\u0004 הוא \u0003מכפר ואינו מכפר שתי כפרות. הן אינן מכפרין כפרתו,\u0004 משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אחת בשנה\",\u0004 לומר ש\u0003כפרה זו\u0004 של שעיר יום הכיפורים הנעשה בפנים \u0003לא תהא אלא אחת בשנה,\u0004 ביום הכיפורים ולא בשאר הימים.","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]:\u0006 \u0003על\u0004 טומאת מקדש וקדשיו \u0003שאין בה ידיעה לא בתחלה ולא בסוף, ועל שאין בה ידיעה בתחלה אבל יש בה ידיעה בסוף, ועל טהור שאכל את הטמא\u0004 — על כל אלה \u0003שעירי הרגלים ושעירי ראשי חדשים ושעיר הנעשה בחוץ מכפרין,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ואילו שעיר הנעשה בפנים שיירה\u0004 \u0005[שייר אותו]\u0006 ר' מאיר, ולא הזכירו, \u0003ו\u0004את \u0003כפרתן\u0004 \u0005[כפרתו]\u0006 של שעיר זה, כלומר על טומאה שיש בה ידיעה בתחילה ואין בה ידיעה בסוף, \u0003נמי שיירה\u0004 \u0005[גם כן שייר אותה],\u0006 ומכאן שהוא ענין בפני עצמו.","שנינו במשנה, \u0003היה ר' שמעון אומר: שעירי ראשי חדשים מכפרין על טהור שאכל את הטמא,\u0004 ושל רגלים מכפרים על שאין בה ידיעה תחילה וסוף, ושל יום הכיפורים מכפר על שיש בה ידיעה בתחילה ואין בה ידיעה בסוף.","ושואלים לשיטתו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ששעירי \u0003ראשי חדשים לא מכפרי\u0004 \u0005[מכפרים]\u0006 על מה שמכפרים שעירי ה\u0003רגלים,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשעיר ראש חודש: \"ואותה נתן לכם לשאת \u0003עון\u0004 העדה\" (ויקרא י, יז), לומר: \u0003עון אחד הוא נושא ואינו נושא שני עונות. אלא\u0004 שעירי ה\u0003רגלים ניכפרו\u0004 \u0005[שיכפרו]\u0006 גם על מה שמכפרים שעירי \u0003ראשי חדשים!\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשעיר ראש חודש: \u0003\"אתה\u0004 נתן לכם לשאת את עון העדה\" (ויקרא י, יז), ונדייק מכאן: \u0003אותה,\u0004 שעיר זה, הוא ה\u0003נושא עון\u0004 זה, \u0003ואין\u0004 שעיר \u0003אחר נושא עון\u0004 זה.","ועוד שואלים לשיטת ר' שמעון: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ששעירי \u0003רגלים לא מכפרין\u0004 על מה שמכפר עליו שעיר \u0003יום הכפורים,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשעיר יום הכיפורים: \u0003\"אחת בשנה\"\u0004 (שמות ל, י), לומר ש\u0003כפרה זו\u0004 של יום הכיפורים \u0003לא תהא אלא אחת בשנה. אלא\u0004 שעירי \u0003יום הכפורים\u0004 \u0003ניכפרו\u0004 \u0005[שיכפרו]\u0006 על מה שמכפרים שעירי ה\u0003רגלים!\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שוב באותו פסוק: \"וכפר על קרנותיו \u0003אחת\",\u0004 לומר \u0003כפרה אחת מכפר ואינו מכפר שתי כפרות.\u0004","ומקשים: \u0003והא כי כתיב\u0004 \u0005[והרי כאשר נאמר]\u0006 \u0003\"אחת\", בשעיר הנעשה בפנים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ולא לגבי שעיר הנעשה בחוץ! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לענין מוספי יום הכיפורים: \"שעיר עזים אחד חטאת \u0003מלבד\u0004"],["\u0003חטאת הכפורים\"\u0004 (במדבר כט, יא), שהיא השעיר הפנימי, \u0003ואיתקוש\u0004 \u0005[והוקש,\u0006 הושווה\u0005]\u0006 בכתוב זה שעיר החטאת \u0003חיצון לפנימי\u0004 להלכות אלו.","שנינו במשנה: \u0003ר' שמעון בן יהודה אומר משמו\u0004 של ר' שמעון ששעירי ראשי חודשים מכפרים רק על טהור שאכל את הטמא. ושעירי הרגלים מכפרים גם על כך, וגם על טומאה שאין בה ידיעה לא בתחילה ולא בסוף. ושעיר חיצון של יום הכיפורים מכפר על שני אלה וגם על טומאה שאין בה ידיעה בתחילה אבל יש בה ידיעה בסוף.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 שעירים של \u0003ראשי חדשים\u0004 ש\u0003לא מכפרי\u0004 \u0005[מכפרים]\u0006 על מה שמכפרים שעירי ה\u0003רגלים?\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על שעיר ראש חודש: \"לשאת את \u0003עון\u0004 העדה\" (ויקרא י, יז), ללמד: \u0003עון אחד הוא נושא ואינו נושא שני עונות;\u0004 אם כן, שעירים של \u0003רגלים נמי לא ניכפרו\u0004 \u0005[גם כן לא יכפרו]\u0006 על מה שמכפרים שעירי \u0003ראשי חדשים,\u0004 שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אתה\",\u0004 ולמדנו מכאן: \u0003אותה\u0004 שעיר של ראש חודש \u0003הוא נושא עון, ואין\u0004 שעיר \u0003אחר נושא עון\u0004 זה! ומשיבים: דרשה זו של \u0003\"אתה\", לא משמע ליה\u0004 \u0005[לו]\u0006 לר' שמעון, לפי דבריו של ר' שמעון בן יהודה.","ועוד שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 שעירים של \u0003רגלים\u0004 ש\u0003לא מכפרי\u0004 \u0005[מכפרים]\u0006 על מה שמכפר שעיר של \u0003יום הכפורים\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי הכפרה ביום הכיפורים: \u0003\"אחת בשנה\"\u0004 (שמות ל, י), לומר ש\u0003כפרה זו לא תהא אלא אחת בשנה,\u0004 ולכן אינה מכפרת ברגלים; אולם \u0003אי הכי\u0004 \u0005[אם כך],\u0006 נאמר כי שעירים (החיצונים) של \u0003יום הכפורים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניכפרו\u0004 \u0005[יכפרו]\u0006 על מה שמכפרים שעירי ה\u0003רגלים,\u0004 שהרי עוד \u0003\"אחת\" כתיב\u0004 \u0005[נאמר]\u0006 באותו פסוק, ללמד: \u0003כפרה אחת מכפר ואינו מכפר שתי כפרות!\u0004 ומשיבים: \u0003\"אחת\" לא משמע ליה\u0004 \u0005[לו]\u0006 לדרוש ממנה ענין זה.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינו דורש כך — משום \u0003דכי כתיב\u0004 \u0005[שכאשר נאמר]\u0006 \u0003\"אחת\"\u0004 — \u0003בשעיר הנעשה בפנים כתיב\u0004 \u0005[נאמר]\u0006 ולא בשעיר החיצון; \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שעירי ה\u0003רגלים נמי נכפרו\u0004 \u0005[גם כן שיכפרו]\u0006 על מה שמכפר שעיר החיצון של \u0003יום הכפורים, דכי כתיב\u0004 \u0005[שכאשר נאמר]\u0006 באותו פסוק \u0003\"אחת\u0004 בשנה\" — \u0003בשעיר הנעשה בפנים כתיב\u0004 \u0005[נאמר],\u0006 ולא בשעיר החיצון. והרי הוא עצמו אמר שאין שעירי הרגלים מכפרים על מה שמכפר השעיר החיצון!","ומשיבים: \u0003לעולם \"אחת\u0004 בשנה\", ממנו למדנו שכפרה זו אינה אלא פעם אחת בשנה, \u0003משמע ליה\u0004 \u0005[לו]\u0006 כמו שאמרנו, בין לשעיר הפנימי ובין לשעיר החיצון, \u0003ושאני הכא\u0004 \u0005[ו\u0006אולם \u0005שונה כאן],\u0006 לענין הדין השני שנלמד מ\"אחת\", שאין קרבן זה מכפר שתי כפרות — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכפר אהרן על קרנתיו אחת בשנה\"\u0004 (שמות ל, י), לומר \u0003קרנותיו\u0004 של \u0003מזבח הפנימי הוא\u0004 ש\u0003כפרה אחת מכפר ואינו מכפר שתי כפרות, הא\u0004 \u0005[הרי]\u0006 שעיר זה שמזים מדמו על קרנות מזבח ה\u0003חיצון\u0004 — \u0003אפילו שתי כפרות\u0004 מכפר.","\u0003אמר עולא אמר ר' יוחנן: תמידין שלא הוצרכו לצבור\u0004 כלומר, כבשים שהופרשו לצורך קרבן התמיד, ולא הוקרבו עד שהחלה שנה חדשה (המתחילה בראש חודש ניסן) שאז צריך להביא קרבנות מכספים חדשים של תרומת הלשכה — \u0003נפדין תמימים,\u0004 רשאים לפדות אותם אף על פי שהם תמימים, ואין ממתינים להם בפדיונם עד שיפול בהם מום, כדרך שנוהגים בבהמות קדשים.","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבה וקאמר לה להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מאן ציית לך\u0004 \u0005[מי מקשיב לך]\u0006 \u0003ולר' יוחנן רבך\u0004 בהלכה זו, שאין הדברים מסתברים כלל! \u0003וכי קדושה שבהן להיכן הלכה?\u0004 והרי בעל חיים שהוקדש בקדושת הגוף להיות קרבן אינו נפדה אלא כשנופל בו מום, וכיצד אפשר לפדות את התמידים הללו כשהם תמימים?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003את לא תסברא דלא אמרינן\u0004 \u0005[\u0006ו\u0005אתה אינך סבור שאין אנו אומרים]\u0006 בעניינים הנוגעים לציבור את הסברה הזו ש\u0003\"קדושה שבהן להיכן הלכה\"? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מותר הקטורת\u0004 שנשארה בסוף השנה במקדש, וצריך להביא קטורת מתרומה חדשה, \u0003מה היו עושין בה? מפרישין ממנה\u0004 עבור \u0003שכר האומנין\u0004 העוסקים בפיטום הקטורת, \u0003ומחללין אותה\u0004 את הקדושה שבה \u0003על מעות האומנין\u0004 כלומר, על המעות שחייבים להם בשכרם (שהרי שכר זה הוא חולין גמורים), \u0003ו\u0004אז, לאחר שנעשתה הקטורת חולין, \u0003נותנין אותה לאומנין בשכרן, וחוזרין ולוקחין\u0004 (קונים) \u0003אותה\u0004 מהם \u0003מ\u0004כספי \u0003תרומה חדשה\u0004 של השנה החדשה.","\u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 הלוא גם כאן \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003קדושה שבהן,\u0004 בקטורת שלא נפסלה, \u0003להיכן הלכה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרבה: \u0003קטורת קאמרת\u0004 \u0005[אומר אתה]?\u0006 אין להוכיח ממנה לתמידים, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003קטורת,\u0004"],["שקדושתה \u0003קדושת דמים הוא,\u0004 שהיא נכס של ההקדש, ואולם אין בה קדושת הגוף לעצמה, עד שתוכנס לכף לשם הקטרה.","הקשה עליו רבה: \u0003אלא מעתה,\u0004 אם כן, כיון שיש בה רק קדושת דמים, \u0003לא תפסל ב\u0004מגע של \u0003טבול יום\u0004 (טמא ביום שטבל לטהרתו, שעדיין אינו רשאי לגעת בתרומה ובקדשים); \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נתנה,\u0004 את הקטורת, \u0003במכתשת\u0004 שבה מכינים אותה — \u0003נפסלת\u0004 מאותה שעה \u0003בטבול יום!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כל\u0004 הדברים שיש בהם \u0003קדושת דמים מיפסלי\u0004 \u0005[נפסלים]\u0006 \u0003בטבול יום, והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המנחות מועלין בהן\u0004 (יש בהן דין מעילה) \u0003משהוקדשו,\u0004 שאף בקדושת דמים יש איסור הנאה מן ההקדש. לאחר ש\u0003קדשו בכלי\u0004 — \u0003הוכשרו\u0004 (נעשו ראויות) \u0003ליפסל בטבול יום, ובמחוסר כפורים\u0004 אם נגע בהן אדם שחייב להביא קרבן לטהרתו (כגון יולדת או זב), \u0003ובלינה\u0004 שאם עבר עליהן הלילה בכלי שרת — נפסלו.","ונדייק מכאן: אם \u0003קדשו בכלי\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הוכשרו ליפסל בטבול יום, אבל אם \u0003לא קדשו בכלי\u0004 — \u0003לא!\u0004","ומקשה עליו רב חסדא: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר, שהקטורת \u0003קדושת הגוף היא? אלא מעתה תיפסל בלינה; אלמה תנן\u0004 \u0005[משום מה שנינו\u0006 במשנה\u0005]:\u0006 \u0003הקומץ\u0004 שקומצים מכל מנחה ומקטירים על המזבח, \u0003והלבונה, והקטורת, ומנחת כהנים\u0004 (שמעלים אותה כולה למזבח), \u0003ומנחת כהן משוח\u0004 (\"מנחת חביתין\", שמביא הכהן הגדול בכל יום), \u0003ומנחת נסכים\u0004 — \u0003מועלים בהן משהוקדשו,\u0004 ואם \u0003קדשו בכלי\u0004 — \u0003הוכשרו ליפסל בטבול יום ובמחוסר\u0004 \u0003כפורים ובלינה.\u0004","ונדייק: \u0003קדשו בכלי\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא קדשו בכלי\u0004 — \u0003לא\u0004 נפסלו בלינה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003לינה קאמרת\u0004 \u0005[אומר אתה]?\u0006 משם אין להוכיח לענין קדושת הקטורת, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003קטורת\u0004 שאינה נפסלת בלינה, למרות שהיא קדושה קדושת הגוף, \u0003הואיל\u0004 וטיבה \u0003וצורתה\u0004 נשמרים \u0003בכל השנה כולה.\u0004","וחוזרים ושואלים: גם אם מוכיחים שהקטורת אכן קדושה בקדושת הגוף, ונמצא שהמשנה מתירה לפדות אותה בעודה ראויה להקרבה, \u0003מכל מקום\u0004 עדיין \u0003קשיא\u0004 \u0005[קשה],\u0006 כפי שהקשה רב חסדא מתחילה על דברי ר' יוחנן בענין תמידים: \u0003וכי קדושה שבהן להיכן הלכה? אמר רבה:\u0004 צריך לומר כי דברים הנלקחים לצורך קרבנות ציבור, \u0003לב בית דין מתנה עליהן,\u0004 בשעת קנייתם, תנאי זה: \u0003אם הוצרכו\u0004 לשימוש בקודש — \u0003הוצרכו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003יהיו\u0004 קדושים רק \u0003לדמיהן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, והא מר\u0004 \u0005[והרי אדוני\u0006 עצמו\u0005]\u0006 \u0003הוא\u0004 ש\u0003אמר: הקדיש זכר\u0004 כלומר, איל זכר הראוי להקרבה, \u0003לדמיו\u0004 בלבד — הריהו \u0003קדוש קדושת הגוף,\u0004 שכיון שהוא תמים וראוי להקרבה חלה עליו קדושת הגוף. וכן נאמר גם בקטורת ובתמידים, שכיון שראוים לכך — תחול עליהם קדושת הגוף! השיב לו רבה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 יש להפריד בין שני אופנים של הקדשה, \u0003הא\u0004 \u0005[זה]\u0006 שקדוש בקדושת הגוף, הרי זה במקרה ש\u0003אמר\u0004 על האיל שהוא קדוש \u0003לדמי עולה,\u0004 שכיון שהוזכר בו שם עולה — חלה עליו קדושת הגוף. \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר\u0004 על האיל שהוא קדוש \u0003לדמי נסכים,\u0004 שמתחילה הוקדש כדי שישתמשו בדמיו לצורך אחר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003פר\u0004 \u0003ושעיר של יום הכפורים שאבדו והפריש אחרים תחתיהם,\u0004"],["\u0003וכן שעירי עבודה זרה\u0004 (שמביא הציבור שחטא בשגגה בעבודה זרה בהוראת בית דין) \u0003שאבדו והפריש אחרים תחתיהן\u0004 והקריבם — \u0003כולן ימותו,\u0004 כדין חטאות שנתכפרו בעליהן, \u0003דברי ר' יהודה. ר' אלעזר ור' שמעון אומרים: ירעו עד שיסתאבו\u0004 (עד שיפול בהם מום), \u0003ו\u0004אז \u0003ימכרו ויפלו דמיהן לנדבה, שאין חטאת צבור מתה.\u0004","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 ימותו או ירעו עד שיסתאבו? \u0003לימא\u0004 \u0005[שנאמר]\u0006 גם כאן: \u0003לב בית דין מתנה עליהן\u0004 וייפדו!","ודחה רבה: שעירים \u0003אבודין קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003אבודין, דלא שכיחי\u0004 \u0005[שאינם מצויים],\u0006 ואין בית דין מתנה על מקרה כזה מתחילה.","והקשה אביי: \u0003הרי פרה\u0004 אדומה, \u0003דלא שכיחא\u0004 \u0005[שאינה מצויה],\u0006 \u0003ו\u0004בכל זאת \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003פרה\u0004 אדומה \u0003נפדית על כל פסול ש\u0004אירע \u0003בה,\u0004 אם \u0003מתה\u0004 — \u0003תפדה,\u0004 אם \u0003נשחטה\u0004 שלא במקום הראוי — \u0003תפדה,\u0004 אם \u0003מצא אחרת נאה הימנה\u0004 — \u0003תפדה,\u0004 אבל אם \u0003שחטה על גבי מערכתה\u0004 כראוי, אלא שמצאו נאה הימנה — \u0003אין לה פדייה עולמית.\u0004 הרי שפרה אדומה נפדית תמימה, למרות שאינה מצויה! והשיב רבה: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה,\u0004 ש\u0003קדשי בדק הבית היא,\u0004 שהרי אין מקריבים אותה על גבי המזבח, ולכן ניתן לפדותה אף בלא שנפל בה מום.","והקשה אביי: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם \u0003מתה או נשחטה תפדה? הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 בפדיון קדשים \u0003העמדה והערכה,\u0004 שצריך להעמיד אותה לפני הכהן כדי שיעריך אותה, ואז תיפדה (ראה ויקרא כז, יא— יב), ואם נשחטה — כיצד מעמידים אותה? והשיב רבה: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר:\u0004 דווקא \u0003קדשי מזבח היו בכלל\u0004 דין זה של \u0003העמדה והערכה\u0004 לצורך פדיונם (אם נופל בהם מום), ואילו \u0003קדשי בדק הבית לא היו בכלל העמדה והערכה,\u0004 ולכן אין צריך להעמידם, ופודה אותם אף לאחר שנשחטו.","והקשה לו אביי: \u0003אי\u0004 \u0005[אם]\u0006 אומר אתה שהברייתא כדעת \u0003ר' שמעון\u0004 היא, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005]:\u0006 \u0003שחטה על גבי מערכתה, אין לה פדייה עולמית.\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: פרה\u0004 אדומה שנשחטה \u0003מטמאה טומאת אוכלין\u0004 אף על פי שאינה מותרת באכילה, \u0003הואיל והיתה לה שעת הכושר,\u0004 שהיתה לה שעה שהיתה ראויה להיפדות ולהיאכל. \u0003ו\u0004מתי היא אותה שעת כושר? \u0003אומר ריש לקיש, אומר היה ר' שמעון: פרה נפדית\u0004 אפילו \u0003על גב מערכתה!\u0004 ואם כן ברייתא זאת אינה כשיטת ר' שמעון.","ואמר רבה: \u0003אלא\u0004 צריך לומר כך: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה, הואיל ודמיה יקרין\u0004 דואגים בית דין להתנות אף במקרה כזה שהוא בלתי שכיח. אגב הדברים, דנים באחד מן הפרטים שהוזכרו בברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם \u0003מתה\u0004 — \u0003תפדה.\u0004 ושואלים על כך: \u0003וכי פודין את הקדשים\u0004 על מנת \u0003להאכילן לכלבים?\u0004 שהרי אם פודים אותה אינה ראויה אלא למאכל כלבים! \u0003אמר רב משרשיא:\u0004 אין פודים אותה לשם הבשר, אלא \u0003משום עורה.\u0004 ושואלים: \u0003וקיימי\u0004 \u0005[ו\u0006כי \u0005עומדים]\u0006 \u0003בית דין ומתנו אדעתא\u0004 \u0005[ומתנים\u0006 רק \u0005על דעת]\u0006 \u0003עורה\u0004 של הפרה? \u0003אמר רב כהנא, אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 בפתגם מקובל: \u0003מגמלא אונה\u0004 \u0005[מהגמל\u0006 את \u0005אוזנו]\u0006 כלומר, אם אתה יכול להציל משהו, הצל אפילו אוזן מגמל.","ושבים לדון בדברי רבה ש\"לב בית דין מתנה\". \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי לרבה ממה ששנינו במשנתנו, \u0003אמרו לו לר' שמעון:\u0004 שעירי ראשי חודשים, שעירי רגלים ושעיר יום הכיפורים, \u0003מהו שיקרבו\u0004 של \u0003זה בזה,\u0004 שלא בזמן שהוקדשו לו מתחילה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003יקרבו, אמרו לו: הואיל ו\u0004לשיטתך \u0003אין כפרתן\u0004 של השעירים השונים \u0003שוה, היאך הן קריבין\u0004 זה בזמנו של זה? \u0003אמר להן: כולן\u0004 יש להם צד שווה, שהם \u0003באין לכפר על טומאת מקדש וקדשיו.\u0004","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נזקקים לכל זה? \u0003לימא\u0004 \u0005[שיאמר]\u0006 כמו שאתה אומר: \u0003לב בית דין מתנה עליהן!\u0004 השיב לו רבה: מדברי \u0003ר' שמעון קאמרת\u0004 \u0005[אומר אתה]\u0006 להקשות? \u0003ר' שמעון לית ליה\u0004 \u0005[אין לו]\u0006 הכלל הזה של \u0003לב בית דין מתנה עליהן,\u0004 כפי ש\u0003אמר רב אידי בר אבין אמר רב עמרם אמר ר' יוחנן: תמידין שלא הוצרכו לצבור, לדברי ר' שמעון\u0004 — \u0003אין נפדין תמימים,\u0004 אלא ממתינים להם עד שיפול בהם מום, \u0003לדברי חכמים\u0004 — \u0003נפדין תמימים.\u0004","ושואלים: \u0003ורבנן דפליגי עליה\u0004 \u0005[ו\u0006אותם \u0005חכמים שחולקים עליו]\u0006 על \u0003ר' שמעון,\u0004 וסבורים שלב בית דין מתנה, \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 חכמים אלה? היכן מבוארת שיטתם? \u0003אי נימא רבנן\u0004 \u0005[אם תאמר\u0006 שהם אותם \u0005חכמים]\u0006 שאמרו את ההלכה בענין \u0003קטורת,\u0004 שנותנים אותה לאומנים בשכרם — אין מכאן ראיה לתמידים,"],["שכן \u0003שאני\u0004 \u0005[שונה]\u0006 היא \u0003קטורת,\u0004 ש\u0003לא בר\u0004 \u0005[בת]\u0006 \u0003רעיה היא,\u0004 שבהמת קרבן יכולה לרעות עד שיפול בה מום, אבל לקטורת אין תקנה כזו, ודווקא משום שאין לה תקנה בדרך אחרת פודים אותה.","\u0003אלא\u0004 נאמר שחכמים הסבורים שתמידים נפדים תמימים הם \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאמרו בענין \u0003פרה\u0004 אדומה שהיא נפדית אפילו מצא אחרת נאה הימנה — יש לדחות גם זאת: \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 דין \u0003פרה\u0004 אדומה, שלב בית דין מתנה עליה כיון ש\u0003דמיה יקרין!\u0004","\u0003ואלא\u0004 נאמר שהם \u0003רבנן\u0004 \u0005[\u0006אותם \u0005חכמים]\u0006 ש\u0003אמרו לו\u0004 לר' שמעון במשנתנו: הואיל ואין כפרתם של השעירים השונים שווה, היאך קרבים זה בזה. ומשמע כי לשיטתם אין קושי בדבר, משום \"שלב בית דין מתנה\".","אולם גם זאת יש לדחות: \u0003ממאי\u0004 \u0005[מנין]\u0006 אתה יודע ששיטת \u0003ר' יהודה היא, והכי קאמר ליה\u0004 \u0005[וכך הוא אומר לו]\u0006 לר' שמעון: \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח\u0006 לשיטתי, \u0005שאני אומר]\u0006 \u0003לב בית דין מתנה עליהן\u0004 — \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003יקרבו\u0004 זה בזה, למרות שאין כפרתם שווה — משום שבית דין מתנה מראש על כך, \u0003אלא לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 \u0003לא,\u0004 שאין בית דין מתנה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יקרבו?\u0004","הרי ניתן להסביר את הדברים אחרת, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \"אמרו לו\" שיטת \u0003ר' מאיר היא,\u0004 \u0003והכי קאמר ליה\u0004 \u0005[וכך הוא אומר לו]\u0006 לר' שמעון: \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 \u0003כל השעירים כפרתן שוה\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003יקרבו, אלא לדידך אמאי\u0004 \u0005[לשיטתך מדוע]\u0006 \u0003יקרבו?\u0004 ואם כן, מניין לר' יוחנן שאכן קיימת שיטת חכמים שתמידים תמימים נפדים!","\u0003אלא\u0004 יש לומר כי \u0003ר' יוחנן גמרא גמיר לה\u0004 \u0005[במסורת למד אותה]:\u0006 \u0003לדברי ר' שמעון\u0004 — \u0003אין נפדין, לדברי חכמים\u0004 — \u0003נפדין.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון\u0004 שאמרנו \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 שאינו מקבל את השיטה ש\u0003לב בית דין מתנה עליהן,\u0004 אותם תמידים שנותרו בסוף השנה, \u0003מאי עבדין להו\u0004 \u0005[מה עושים להם]?\u0006 \u0003אמר ר' יצחק אמר ר' יוחנן: מקיצין בהן את המזבח\u0004 כלומר, מקריבים אותם כעולות לנדבת הציבור בזמן שאין על המזבח קרבן אחר, כדי שלא יישאר המזבח ריקם.","\u0003אמר ר' שמואל בר רב יצחק: ומודה ר' שמעון בשעירי חטאת, שאין מקיצין\u0004 את המזבח \u0003בגופן, אלא בדמיהן,\u0004 שירעו עד שיפול בהם מום, ואז ימכרו אותם, ובדמיהם יקנו קרבנות לעולה.","כי דווקא \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי תמידים, כן \u0003הוא, דמעיקרא\u0004 \u0005[\u0006לפי \u0005שמתחילה]\u0006 היו אלה כבשים שנועדו לקרבן \u0003עולה, והשתא\u0004 \u0005[ו\u0006גם \u0005עכשיו]\u0006 הם \u0003עולה. אבל התם\u0004 \u0005[שם]\u0006 בשעירי חטאת, \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 הוקדשו לקרבן \u0003חטאת והשתא\u0004 \u0005[ועכשיו]\u0006 רוצים להקריבם \u0003עולה\u0004 — יש לעשות \u0003גזירה\u0004 שלא להקריבם לעולה \u0003לאחר כפרה\u0004 כלומר, לאחר שכבר נתכפרו הציבור באחרים, \u0003אטו\u0004 \u0005[משום]\u0006 חשש שמא יבואו להקריב חטאת לשם עולה \u0003לפני כפרה\u0004 כלומר, גם במקרה שלא נתכפרו עדיין בחטאת אחרת.","\u0003אמר אביי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 מעין הדברים האלה: \u0003פר ושעיר של יום הכפורים שאבדו והפריש אחרים תחתיהם, וכן שעירי עבודה זרה שאבדו והפריש אחרים תחתיהן\u0004 — \u0003כולן ימותו, דברי ר' יהודה. ר' אלעזר ור' שמעון אומרים: ירעו עד שיסתאבו\u0004 (עד שיפול בהם מום), \u0003ו\u0004אז \u0003ימכרו ויפלו דמיהן לנדבה, שאין חטאת צבור מתה.\u0004","ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 ימתינו להם שיסתאבו? \u0003נקרבו אינהו גופייהו\u0004 \u0005[שיקרבו הם עצמם]\u0006 כקרבן \u0003עולה! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי יש בדבר \u0003גזירה\u0004 שלא יקרבו לעולה \u0003לאחר כפרה אטו\u0004 \u0005[משום]\u0006 \u0003לפני כפרה.\u0004","\u0003אמר רבא\u0004 והוסיף, \u0003אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 מעין זה: כאשר אבד אחד משני השעירים של יום הכיפורים (לה' או לעזאזל), מביאים זוג אחר ומגרילים עליהם. האחד ייעשה בן זוג לראשון, \u0003והשני\u0004 מן הזוג השני, שלא נעשה בו שימוש, \u0003ירעה עד שיסתאב, וימכר ויפלו דמיו לנדבה.\u0004","ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 עושים כן? ש\u0003יקרב איהו גופיה\u0004 \u0005[הוא עצמו]\u0006 \u0003עולה! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי יש \u0003גזרה\u0004 שלא להקריבו עולה \u0003אחר כפרה אטו\u0004 \u0005[משום]\u0006 \u0003לפני כפרה.\u0004","\u0003אמר רבינא, אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 כיוצא בזה: \u0003אשם שמתו בעליו או שנתכפרו בעליו\u0004 — \u0003ירעה עד שיסתאב וימכר, ויפלו דמיו לנדבה. ר' אליעזר אומר: ימות,\u0004 ולא ימכר. \u0003ר' יהושע אומר: יביא בדמיו עולה.\u0004","ויש לשאול על דברי ר' יהושע: \u0003וליקרב הא גופא\u0004 \u0005[ושיקרב הוא עצמו]\u0006 \u0003עולה! אלא לאו\u0004 \u0005[האם לא]\u0006 טעם דבריו בגלל \u0003גזירה לאחר כפרה אטו\u0004 \u0005[משום]\u0006 \u0003לפני כפרה.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 ברייתא אחרת\u0005]\u0006 כדברי ר' יוחנן לעיל, שלשיטת ר' שמעון, תמידים תמימים שנותרו מקייצים בהם את המזבח: \u0003מה הן מביאין מן המותרות\u0004 של הקרבנות שנתרמו לציבור ולא נעשה בהם שימוש באותה שנה?"],["\u0003קיץ כבנות שוח\u0004 (קינוח סעודה כמין תאנים) \u0003למזבח.\u0004 ותוהים: וכי אפשר להעלות תאנים על המזבח? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כי כל שאר וכל דבש\u0004 לא תקטירו ממנו אשה לה' \"(ויקרא ב, יא), ואף כל פירות העץ בכלל זה! ומשיבים, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב חנינא:\u0004 מביאים מן המותרות קיץ למזבח \u0003כבנות שוח\u0004 שמביאים בקינוח סעודה \u0003לאדם.\u0004","\u0003דרש רב נחמן בר רב חסדא\u0004 ברבים: \u0003אין מקיצין\u0004 כלומר, אין מביאים את קיץ המזבח \u0003בעולת העוף. אמר רבא: הא בורכא\u0004 \u0005[זוהי שטות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: מאי בורכתא\u0004 \u0005[מה השטות\u0006 שבדבר\u0005]?\u0006 \u0003אנא אמריתה ניהליה\u0004 \u0005[אני אמרתי אותה\u0006 את האימרה הזו \u0005לו],\u0006 \u0003ומשמיה\u0004 \u0005[ומשמו]\u0006 של \u0003רב שימי מנהרדעא אמריתה ניהליה\u0004 \u0005[אמרתי אותה לו],\u0006 ש\u0003אמר רב שימי מנהרדעא: מותרות\u0004 \u0003לנדבת צבור אזלי\u0004 \u0005[הולכים],\u0006 \u0003ואין עולת עוף בצבור.\u0004","ושבים לענין הראשון, ומעירים: \u0003ואף שמואל סבר להא\u0004 \u0005[\u0006כהלכה \u0005זו]\u0006 של \u0003ר' יוחנן,\u0004 שאמר כי לדעת ר' שמעון, תמידים תמימים שנותרו יקרבו לקיץ המזבח, למרות שלא הוקדשו מתחילה לכך אלא לקרבן חובה, ש\u0003אמר רב יהודה אמר שמואל: קרבנות צבור\u0004 — \u0003סכין\u0004 היא ה\u0003מושכתן למה שהן\u0004 כלומר, בשעת שחיטה נקבע למה הם שייכים, ועד אז ניתן להחליט עליהם דלשם איזה קרבן הם מוקרבים כעולה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 לענין חטאת: \u0003ומודה ר' שמעון בשעיר\u0004 חטאת של מוספי הרגלים, \u0003שאם לא קרב\u0004 השעיר \u0003ברגל יקרב בראש חדש, ואם לא קרב בראש חדש יקרב ביום הכפורים, ואם לא קרב ביום הכפורים יקרב ברגל, ואם לא קרב ברגל זה יקרב ברגל אחר, שמתחלתו לא בא אלא לכפר על מזבח החיצון.\u0004","ומביאים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא הוקדש\u0004 שעיר החטאת \u0003אלא לכפר על מזבח החיצון.\u0004","שנינו במשנה: \u0003ועל זדון טומאת מקדש וקדשיו שעיר הנעשה בפנים\u0004 ויום הכיפורים מכפרים. ושואלים על כך: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שמכפר על הזדונות?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בענין שעיר הנעשה פנים: \u0003\"וכפר על הקדש מטמאת בני ישראל\u0004 ומפשעיהם לכל חטאתם\" (ויקרא טז, טז), וביאור הדברים הנזכרים: \u0003פשעים\u0004 — \u0003אלו המרדים, וכן הוא אומר\u0004 בדברי יהורם מלך ישראל ליהושפט מלך יהודה: \u0003\"מלך מואב פשע בי\"\u0004 (מלכים ב ג, ז), כלומר מרד בי. \u0003ואומר: \"אז תפשע לבנה בעת ההיא\"\u0004 (מלכים ב ח, כב), משמע שפשע הוא מרידה, וכוונתו — מי שעושה עבירה בזדון. \u0003חטאות\u0004 — \u0003אלו השגגות, וכן הוא אומר: \"נפש כי תחטא בשגגה\"\u0004 (ראה ויקרא ד, כז).","שנינו במשנה: \u0003על שאר עבירות שבתורה, הקלות והחמורות, הזדונות והשגגות,\u0004 הודע ולא הודע, עשה ולא תעשה, כריתות ומיתות בית דין — שעיר המשתלח מכפר.","על לשון המשנה תוהים: \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003קלות היינו\u0004 \u0005[זהו]\u0006 \u0003עשה ולא תעשה, חמורות היינו\u0004 \u0005[זהו]\u0006 \u0003כריתות ומיתות בית דין, הודע היינו\u0004 \u0005[זהו]\u0006 \u0003מזיד, לא הודע היינו\u0004 \u0005[זהו]\u0006 \u0003שוגג!\u0004 ומפני מה חזר וכפל אותו ענין עצמו?","\u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר]:\u0006 \u0003על שאר עבירות שבתורה, בין קלות בין חמורות, בין שעשאן בשוגג בין שעשאן במזיד.\u0004 ולגבי \u0003אותן שעשאן בשוגג — בין נודע לו ספיקן\u0004 (שנוגע לו שעבר על ספק עבירה) לפני יום הכיפורים, \u0003בין לא נודע לו ספיקן\u0004 — על כולם מכפר שעיר זה. ואחר כך חוזר ומפרש את הדברים במשנה: \u0003ואלו הן קלות\u0004 — מצוות \u0003עשה ולא תעשה, ואלו הן חמורות\u0004 — \u0003כריתות ומיתות בית דין.\u0004","ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003עשה\u0004 שמתכפר בשעיר המשתלח ביום הכיפורים \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דלא עבד\u0004 \u0005[אם שלא עשה]\u0006 החוטא \u0003תשובה\u0004 — הלוא אמרו: \u0003\"זבח רשעים תועבה\"\u0004 (משלי כא, כז), והקרבן אינו מועיל לכפר. \u0003אי דעבד\u0004 \u0005[אם שעשה]\u0006 \u0003תשובה,\u0004 הרי \u0003כל יומא נמי\u0004 \u0005[יום גם כן]\u0006 מתכפר לו, אף שאינו יום הכיפורים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עבר על מצות עשה ועשה תשובה, לא זז משם עד שמוחלין לו,\u0004 ואם כן אינו נזקק לשעיר המשתלח!","\u0003אמר ר' זירא:\u0004"],["יש לפרש שמדובר פה \u0003בעומד במרדו\u0004 ולא עשה תשובה כלל, ומכל מקום מתכפר לו בשעיר המשתלח, \u0003ו\u0004שיטת \u0003רבי היא\u0004 הסבור שיום הכיפורים מכפר אף על שאינם שבים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: על כל עבירות שבתורה, בין עשה תשובה בין לא עשה תשובה\u0004 — \u0003יום הכפורים מכפר, חוץ מ\u0004מי שהוא \u0003פורק עול\u0004 שכופר בעיקר, \u0003ו\u0004כן ה\u0003מגלה פנים בתורה\u0004 שמדבר על התורה בחוצפה ובזלזול, \u0003ו\u0004זה ה\u0003מפר ברית בבשר\u0004 שאינו מקיים את מצות ברית מילה, \u0003ש\u0004על אלה רק \u0003אם עשה תשובה\u0004 — \u0003יום הכפורים מכפר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין יום הכפורים מכפר.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 מה מקור דבריו של \u0003רבי? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הכתוב \"כי דבר ה' בזה ואת מצוותו הפר הכרת תכרת הנפש ההוא עונה בה\" (במדבר טו, לא): \u0003\"כי דבר ה' בזה\" —\u0004 \u0003זה הפורק עול ומגלה פנים בתורה,\u0004 שהוא מבזה את דבר ה' בתורתו; \u0003\"ואת מצותו הפר\"\u0004 — \u0003זה המפר ברית בבשר;\u0004 ומה שנאמר \u0003\"הכרת תכרת\"\u0004 בלשון כפולה יש לפרשו: \u0003\"הכרת\"\u0004 — כוונתו \u0003לפני יום הכפורים, \"תכרת\"\u0004 — \u0003לאחר יום הכפורים.\u0004","\u0003יכול\u0004 יהא כרת זה חל \u0003אפילו עשה תשובה? תלמוד לומר: \"עונה בה\"\u0004 — \u0003לא אמרתי\u0004 שתיכרת \u0003אלא בזמן שעונה בה\u0004 ולא חזר בתשובה. ודברים אלה אמורים דווקא בשלוש עבירות אלה, אבל בעבירות אחרות — יום הכיפורים מכפר על הנפש אפילו כשעוונה בה.","ומן הצד האחר, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על רבי, כיצד הם מפרשים? \u0003\"הכרת\"\u0004 — \u0003בעולם\u0004 \u0003הזה, \"תכרת\"\u0004 — \u0003לעולם הבא, \"עונה בה\"\u0004 — \u0003שאם עשה תשובה ומת, מיתה ממרקת\u0004 גומרת לכפר עוונותיו.","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד אותה\u0006 את משנתנו\u0005]\u0006 \u0003כ\u0004שיטת \u0003רבי? והא מדסיפא\u0004 \u0005[והרי מכיון שבסופה]\u0006 שיטת \u0003ר' יהודה היא, רישא נמי\u0004 \u0005[בראשה גם כן]\u0006 שיטת \u0003ר' יהודה היא!\u0004 ומנין לנו שסופה שיטת ר' יהודה היא — \u0003דקתני סיפא\u0004 \u0005[ששנה בסוף\u0006 בהמשך המשנה\u0005]:\u0006 \u0003אחד ישראל ואחד כהנים ואחד כהן משוח\u0004 כולם מתכפרים בשעיר המשתלח, \u0003ומאן אית ליה האי סברא\u0004 \u0005[ומי יש לו\u0006 מחזיק ב\u0005סברה זו]?\u0006 \u0003ר' יהודה\u0004 כמבואר בברייתא להלן (עמוד ב), ואם המשך המשנה הוא לשיטת ר' יהודה, \u0003מכלל\u0004 הדברים יש ללמוד \u0003דרישא\u0004 \u0005[ש\u0006גם \u0005ההתחלה]\u0006 כשיטת \u0003ר' יהודה!\u0004","\u0003אמר רב יוסף:\u0004 אין זו קושיה, אפשר לומר שמשנתנו כולה כשיטת \u0003רבי היא,\u0004 \u0003ו\u0004אולם \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהודה\u0004 לענין כפרה בשעיר המשתלח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דוקא קאמר מר\u0004 \u0005[\u0006האם \u0005בדקדוק אמר אדוני],\u0006 ש\u0003רבי סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהודה\u0004 שהשעיר המשתלח מכפר על כולם, \u0003אבל\u0004 ייתכן ש\u0003ר' יהודה לא סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרבי\u0004 לענין כפרה בלא תשובה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מ\u0004כיון ש\u0003רבי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה, אף ר' יהודה סבר לה נמי\u0004 \u0005[סבור גם כן]\u0006 \u0003כרבי, מיהו אורחא דמילתא קתני\u0004 \u0005[אבל בדרך ארץ\u0006 אדוני \u0005שונה],\u0006 שכך דרך ארץ \u0003למימר\u0004 \u0005[לומר]\u0006 ש\u0003תלמיד סבר לה כרביה\u0004 \u0005[סבור כרבו]\u0006 ואין אומרים שהרב סבור כתלמידו. וכיון שהיה רבי תלמידו של ר' יהודה שונה הוא כך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דוקא קאמינא\u0004 \u0005[בדקדוק אני אומר]\u0006 ש\u0003רבי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה, אבל ר' יהודה לא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרבי.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בסיפרא (מדרש ההלכה לספר ויקרא): \u0003יכול יהא יום הכפורים מכפר על שבים ועל שאינן שבים? ו\u0004לכאורה \u0003דין הוא,\u0004 אפשר להכריע בדבר מן הסברה: \u0003הואיל ו\u0004קרבן \u0003חטאת ו\u0004קרבן \u0003אשם מכפרין, ו\u0004גם \u0003יום הכפורים מכפר,\u0004 יש ללמוד: \u0003מה חטאת ואשם אין מכפרין אלא על השבים\u0004 בתשובה מאותה עבירה עליה הביאו את הקרבן, \u0003אף יום הכפורים אין מכפר אלא על השבים!\u0004 ויש לדחות את ההשוואה ולומר: \u0003מה לחטאת ואשם\u0004 שאין מכפרים אלא על השבים, \u0003ש\u0004הרי \u0003אין מכפרין על המזיד כשוגג, תאמר ליום הכפורים שמכפר\u0004 אף \u0003על המזיד כשוגג,\u0004","ו\u0003הואיל ומכפר על המזיד כשוגג,\u0004 שמא \u0003יכפר\u0004 גם \u0003על שבים ועל שאינן שבים? תלמוד לומר: \"אך\u0004 בעשור לחדש השביעי הזה יום כפורים הוא\" (ויקרא כג, כז), ו\"אך\" שהוא לשון מיעוט באה ל\u0003חלק,\u0004 לומר שאף שמכפר על הזדונות אינו מכפר אלא עם התשובה.","שיטת \u0003סתם סיפרא\u0004 כשלא נזכר בו שם חכם אחר, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה\u0004 היא, \u0003וקאמר\u0004 \u0005[והוא אומר]:\u0006 \u0003שבים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מתכפרים בו, \u0003לא שבים\u0004 — \u0003לא.\u0004 הרי שאינו סבור כדעת רבי.","\u0003ו\u0004אגב כך \u0003רמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מ\u0003סתם סיפרא\u0004 בברייתא זו, \u0003אסתם\u0004 \u0005[על סתם]\u0006 \u0003סיפרא\u0004 שבמקום אחר, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 אחרת בספרא: \u0003יכול לא יהא יום הכפורים מכפר אלא אם כן התענה בו וקראו מקרא קדש\u0004 כלומר, נהג בו מנהג קדושה, \u0003ולא עשה בו מלאכה.\u0004 אבל אם \u0003לא התענה בו\u0004 ביום הכיפורים, \u0003ולא קראו מקרא קדש, ועשה בו מלאכה, מנין\u0004 שגם אז יום הכיפורים מכפר? \u0003תלמוד לומר: \"יום כפרים הוא\"\u0004 (ויקרא כג, כח), לומר ש\u0003מכל מקום\u0004 מכפר!","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא השניה כשיטת \u0003רבי, והא\u0004 \u0005[וזו]\u0006 הראשונה כשיטת \u0003ר' יהודה.\u0004","\u0003רבא אמר: הא והא\u0004 \u0005[זו וזו]\u0006 שיטת \u0003רבי\u0004 היא, שיום הכיפורים מכפר גם לשאינם שבים, אבל הברייתא האומרת שמכפר רק לשבים מדברת במקרה מיוחד, בעבירות הנוגעות ליום הכיפורים עצמו, כי \u0003מודה רבי בכרת דיומא\u0004 \u0005[של היום,\u0006 יום הכיפורים עצמו\u0005],\u0006 אם אכל או עשה מלאכה ביום הכיפורים, שאין מכפר עליו יום הכיפורים אלא אם כן עשה תשובה על עבירה זו. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 אלא שיש לעבירות אלה דין שווה לכל העבירות, ויום הכיפורים מכפר גם עליהן בכל מקרה — יש לתמוה: וכי \u0003כרת\u0004 של \u0003יום הכפורים לרבי לית ליה\u0004 \u0005[אין לו]?\u0006 והרי נמצא שאין אדם נענש כרת כלל על אכילה ועשיית מלאכה ביום הכיפורים!","על הוכחה זו מקשים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 \u0003משכחת לה\u0004 \u0005[יכול אתה למצוא אותה]\u0006 שייענש על חילול היום, \u0003כגון דעבד בליליא\u0004 \u0005[שעשה עבירה\u0006 וחילל את קדושת היום \u0005בלילה]\u0006 של יום הכיפורים, \u0003ומית\u0004 \u0005[ומת]\u0006 באותו לילה, \u0003דלא אתא יממא לכפורי ליה\u0004 \u0005[ש\u0006עדיין \u0005לא בא היום\u0006 כדי \u0005לכפר לו],\u0006 שאין מכפר אלא היום ולא הלילה!","\u0003אלא\u0004 יש לתקן את הלשון, ובמקום זה \u0003אימא\u0004 \u0005[אמור]\u0006 שכך אמר רבא:"],["מודה רבי בכרת של יום הכיפורים עצמו שאינו מתכפר בלא תשובה, שאם לא נאמר כן, כי ו\u0003כרת דיממא\u0004 \u0005[של יומו\u0006 של יום הכיפורים\u0005]\u0006 \u0003ל\u0004דעת \u0003רבי לית ליה\u0004 \u0005[אין לו]?\u0006","ודוחים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא? משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 במקרה ש\u0003אכל אומצא\u0004 \u0005[חתיכת בשר]\u0006 \u0003וחנקיה ומית\u0004 \u0005[וחנקו\u0006 הבשר \u0005ומת],\u0006 שכיון שנחנק מיד לא היה זמן ביום הכיפורים לכפר לו לאחר העבירה. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 ש\u0003אכל סמוך לשקיעת החמה\u0004 בסוף היום, ש\u0003לא הוה\u0004 \u0005[היתה]\u0006 \u0003שהות\u0004 ביום \u0003לכפורי ליה\u0004 \u0005[לכפר לו]\u0006 על אכילתו זו.","שנינו במשנה ששעיר המשתלח מכפר, \u0003אחד ישראל ואחד כהנים ואחד כהן משוח.\u0004","ושואלים: \u0003הא גופא קשיא\u0004 \u0005[\u0006משנה \u0005זו עצמה קשה],\u0006 שכן בתחילה \u0003קתני\u0004 \u0005[שנה\u0006 בה\u0005]:\u0006 \u0003אחד ישראל ואחד כהנים ואחד כהן משוח,\u0004 משמע שכולם שווים, \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003מה\u0004 ההבדל \u0003בין ישראל לכהנים ולכהן משוח,\u0004 משמע שיש הבדל ביניהם ואינם שווים! \u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אחד ישראל ואחד כהנים ואחד כהן משוח מתכפרין בשעיר המשתלח בשאר עבירות, ואין חילוק ביניהן\u0004 בענין זה. \u0003ומה בין ישראל לכהנים ולכהן משוח? אלא\u0004 לענין טומאת מקדש וקדשיו, \u0003שהפר מכפר על הכהנים על טומאת מקדש וקדשיו\u0004","\u0003ומני\u0004 \u0005[ושיטת מי היא]\u0006 משנתנו — שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ששנויה ברייתא]\u0006 על הכתוב \"וכפר את מקדש הקדש ואת אהל מועד ואת המזבח יכפר ועל הכהנים ועל כל עם הקהל יכפר\" (ויקרא טז, לג): \u0003\"וכפר את מקדש הקדש\" —\u0004 \u0003זה\u0004 כפרה של \u0003לפני ולפנים\u0004 (קדש הקדשים), \"ו \u0003את אהל מועד\"\u0004 — \u0003זה היכל,\u0004 \"ואת ה\u0003מזבח\"\u0004 — \u0003כמשמעו, \"יכפר\"\u0004 — \u0003אלו עזרות,\u0004 \"ועל ה\u0003כהנים\"\u0004 שנאמר שם — \u0003כמשמעו,\u0004 \"ועל כל \u0003עם הקהל\"\u0004 — \u0003אלו ישראל, \"יכפר\"\u0004 שמוסיף — \u0003אלו הלוים;\u0004","\u0003הושוו כולן\u0004 כהנים, ישראל ולויים \u0003לכפרה אחת, שמתכפרין בשעיר המשתלח בשאר עבירות,\u0004 אבל בטומאת מקדש וקדשיו הם שונים מישראל, שעל ישראל מכפרים השעירים הפנימי והחיצון, ועל הכהנים מכפר פר החטאת, \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' שמעון אומר: כשם שדם שעיר הנעשה בפנים מכפר על ישראל על טומאת מקדש וקדשיו, כך דם הפר\u0004 שנזרק בפנים \u0003מכפר על הכהנים על טומאת מקדש וקדשיו, וכשם שוידויו של שעיר המשתלח מכפר על ישראל בשאר עבירות, כך וידויו של פר מכפר על הכהנים בשאר עבירות.\u0004","ושואלים: \u0003ולר' שמעון, הא\u0004 \u0005[הרי]\u0006 \u0003ודאי הושוו\u0004 כולם בפסוק זה! ומשיבים: לשיטתו \u0003מאי\u0004 \u0005[במה]\u0006 \u0003הושוו?\u0004 ש\u0003בני כפרה נינהו\u0004 \u0005[הם]\u0006 שכולם מתכפרים ביום הכיפורים, \u0003מיהו\u0004 \u0005[אולם]\u0006 \u0003כל חד וחד מכפר בדנפשיה\u0004 \u0005[אחד ואחד מתכפר בשל עצמו].\u0006","ומבררים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון\u0004 שהכהנים אינם מתכפרים בשעיר המשתלח? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקח את שני השעירם\"\u0004 (ויקרא טז, ז), \u0003איתקש\u0004 \u0005[הוקש,\u0006 הושווה בכתוב זה\u0005]\u0006 \u0003שעיר המשתלח לשעיר הנעשה בפנים, מה שעיר הנעשה בפנים אינו מכפר על הכהנים על טומאת מקדש וקדשיו, דכתיב ביה\u0004 \u0005[ש\u0006הרי \u0005נאמר בו]:\u0006 \"ושחט את שעיר החטאת \u0003אשר לעם\u0004 והביא את דמו אל מבית לפרכת\" (ויקרא טז, טו), \u0003אף שעיר המשתלח אינו מכפר על הכהנים בשאר עבירות.\u0004","\u0003ור' יהודה אמר לך\u0004 \u0005[יכול לומר לך]\u0006 כנגד זה: \u0003להכי איתקוש\u0004 \u0005[לכך הוקשו]\u0006 השעירים, לומר \u0003שיהיו שוים במראה ובקומה ובדמים\u0004 (במחיר), לזה \u0003הוא דאתא\u0004 \u0005[שבא\u0006 הכתוב\u0005],\u0006 אבל לא לענין כפרתם.","ומבררים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את\u0006 הברייתא \u0005הזו ששנו חכמים]:\u0006 נאמר \u0003\"ושחט את שעיר החטאת אשר לעם\"\u0004 (ויקרא טז, טז) — ללמד שהוא לכפרת העם דווקא, \u0003שאין הכהנים מתכפרין בו; ובמה מתכפרין? בפרו של אהרן.\u0004","\u0003יכול לא יתכפרו בפרו של אהרן, שהרי כבר נאמר:\u0004 \"פר החטאת \u0003אשר לו\"\u0004 (ויקרא טז, ו), ומשמע — אשר לו ולא לאחרים, אם כן \u0003מעתה,\u0004 אם כך אתה אומר — \u0003אין להן כפרה\u0004 כלל! \u0003כשהוא אומר: \"יכפר על הכהנים\"\u0004 (ראה ויקרא טז, לג) — \u0003מצינו\u0004 שיש \u0003להן כפרה.\u0004","ואם כן, \u0003במה הן מתכפרין? מוטב\u0004 לומר \u0003שיתכפרו בפרו של אהרן, שהרי הותר מכללו אצל ביתו,\u0004 שהרי הפר אינו מכפר רק עליו, אלא גם על ביתו, כלשון הכתוב \"וכפר בעדו ובעד ביתו\" (ויקרא טז, ו), \u0003ואל יתכפרו בשעיר הנעשה בפנים, שלא הותר מכללו אצל ביתו.\u0004","\u0003ואם נפשך\u0004 (רצונך) \u0003לומר\u0004 ולהקשות על ראיה זו — הרי ראיה אחרת, \u0003הרי הוא אומר\u0004 בכתובים: \"בית ישראל ברכו את ה', \u0003בית אהרן ברכו את ה', בית הלוי ברכו את ה', יראי ה' ברכו את ה' \"\u0004(תהלים קלה, יט), הרי זה מלמד שבכלל \"וכפר בעדו ובעד ביתו\" כל הכהנים כולם, ולאו רק בני משפחתו של הכהן הגדול.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 \u0003תנא\u0004 זה ששנה ברייתא זו? \u0003אמר ר' ירמיה:\u0004 הרי זה ש\u0003לא כ\u0004דעת \u0003ר' יהודה, דאי\u0004 \u0005[שאם]\u0006 כדעת \u0003ר' יהודה,\u0004 מה שנאמר שאם אינם מתכפרים בפרו של אהרן אין להם כפרה אינו מתאים לשיטתו. \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003כהנים יש להן כפרה בשעיר המשתלח.\u0004 ושואלים: \u0003ומני\u0004 \u0005[ו\u0006שיטת \u0005מי היא]?\u0006 \u0003רבא אמר:\u0004 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: כהנים אין להם כפרה בשעיר המשתלח.\u0004","\u0003אביי אומר: אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת \u0003ר' יהודה\u0004 היא, \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אם אין הכהנים מתכפרים בפרו של אהרן, \u0003מעתה אין להם כפרה בטומאת מקדש וקדשיו?\u0004 \u0003כשהוא אומר: \"יכפר על הכהנים\"\u0004 (ויקרא טז, לג) — \u0003מצינו שיש להן כפרה בשאר עבירות\u0004 כפי שראינו לעיל, שלשיטת ר' יהודה הושוו גם הכהנים בפסוק זה לכפרה בשעיר המשתלח. \u0003וכמו\u0004 ש\u0003מצינו שיש להן כפרה בשאר עבירות, כך יש להן כפרה\u0004"]]};
